#!/usr/bin/env node
/* Books-2 batch2 psychiatry wave: topic map only, own words, new MCQs only. */
import fs from "node:fs";
import path from "node:path";
import { createRequire } from "node:module";
import { fileURLToPath } from "node:url";
const require = createRequire(import.meta.url);
const LP = require("../prep-lessons.js");
const ROOT = path.join(path.dirname(fileURLToPath(import.meta.url)), "..");
const REF = "Psychiatry topic map (Marrow e6 topic selection only; text rewritten in own words, no verbatim copy)";
function mcq(id, q, o, a, exp, r, kp) { return { id, q, o, a, exp, r, kp }; }
function step(tx, say, vis) { return vis ? { tx, say, vis } : { tx, say, vis: null }; }
function tbl(cols, rows) { return { kind: "table", cols, rows }; }
function cmp(lt, lp, rt, rp) { return { kind: "compare", left: { title: lt, points: lp }, right: { title: rt, points: rp } }; }
const M = [];
function add(id, title, kb, kbName, aliases, steps, pearls, patho, diffs, invs, mcqs) { M.push({ id, title, kb, kbName, aliases, steps, pearls, patho, diffs, invs, mcqs }); }

add("psy-psychopathology", "Psychopathology", "psychopathology", "Psychopathology",
 ["Delusions", "Hallucinations", "Formal thought disorder", "Mental status examination"],
 [step("**Psychopathology** is the precise description of abnormal mental experience, behaviour and cognition, recorded without premature diagnosis. Form (how a symptom is structured) matters more than content (its theme): a belief is classified by fixity and plausibility, not by whether its topic is persecution or jealousy. Accurate description drives reliable diagnosis across clinicians.", "Describe symptoms by form, not theme. Fixity and plausibility classify a belief, not its topic."),
  step("**Delusions** are fixed false beliefs held with absolute conviction despite contradictory evidence and not shared by the person's culture. Primary delusions arrive fully formed (delusional percept attaches delusional meaning to a normal perception), while secondary delusions elaborate from mood or hallucinations. Delusional mood, misidentification (Capgras: familiar person replaced by impostor; Fregoli: stranger is familiar person in disguise) and somatic, grandiose, persecutory and referential themes recur in examinations.", "Fixed, unshakeable, culturally alien beliefs are delusions. Capgras says impostor; Fregoli says disguised familiar."),
  step("**Hallucinations** are perceptions without external stimulus, experienced as real and in external space, distinguished from illusions (misinterpretation of a real stimulus), pseudohallucinations (recognised as internal, in inner space) and hypnagogic or hypnopompic phenomena on sleep borders which are normal. Auditory hallucinations dominate psychosis; visual hallucinations suggest organic disease; tactile formication suggests stimulant or alcohol related states.", "Perception without stimulus is hallucination. Visual hallucinations point organic; misread real stimuli are illusions."),
  step("**Formal thought disorder** shows in speech structure: loosening of associations, tangentiality, circumstantiality, word salad, neologisms, clang associations, perseveration and thought block. Schneider first rank symptoms (thought insertion, withdrawal, broadcasting, third person and running commentary hallucinations, delusional perception, passivity) historically flagged schizophrenia but occur in other psychoses and no longer carry diagnostic primacy. Negative symptoms (affective flattening, alogia, avolition, anhedonia) predict function better than positive ones.", "Disordered speech form reveals thought disorder. First rank symptoms occur beyond schizophrenia. Negative symptoms drive disability.", tbl(["Phenomenon", "Stimulus", "Insight and space"], [["Hallucination", "Absent", "Real, external space, no insight"], ["Illusion", "Present but misread", "Corrects with attention"], ["Pseudohallucination", "Absent", "Recognised internal, inner space"], ["Hypnagogic imagery", "Sleep onset", "Normal phenomenon"]]))],
 ["Delusion judged by fixity, not bizarreness of theme alone", "Visual hallucination means organic cause until disproven", "Capgras impostor versus Fregoli disguised familiar", "Negative symptoms predict long term function"],
 "Aberrant salience and predictive processing failures tag neutral stimuli with threatening significance, while source monitoring errors misattribute inner speech to external agents, generating hallucinations and passivity phenomena.",
 ["Delusion versus overvalued idea (comprehensible, less fixed)", "Hallucination versus illusion versus pseudohallucination", "First rank symptoms in schizophrenia versus mania psychosis"],
 ["Structured mental status examination and verbatim speech recording", "Collateral history for fixity and cultural context", "Organic screen when hallucinations are visual or clouded"],
 [mcq("bk2-psy-001", "A belief held with absolute conviction despite irrefutable contrary evidence, not culturally shared, is what?", ["Overvalued idea", "Delusion", "Obsession", "Phobia"], 1, "Delusions are defined by fixity, falsehood and cultural incongruence. Overvalued ideas are comprehensible and held less absolutely; obsessions are recognised as own and resisted; phobias are fears recognised as excessive.", ["Incorrect. Overvalued ideas allow some doubt and comprehensibility.", "Correct. Fixed false culturally alien belief is delusion.", "Incorrect. Obsessions are ego dystonic and resisted.", "Incorrect. Phobia is recognised excessive fear."], "Unshakeable plus false plus alien equals delusion."),
  mcq("bk2-psy-002", "Patient insists his wife has been replaced by an identical impostor. This is which phenomenon?", ["Fregoli syndrome", "Capgras syndrome", "Cotard syndrome", "Ekbom syndrome"], 1, "Capgras is delusional misidentification that a familiar person is replaced by an impostor. Fregoli is opposite (stranger is familiar in disguise); Cotard is nihilistic nonexistence; Ekbom is infestation delusion.", ["Incorrect. Fregoli believes strangers are familiar people disguised.", "Correct. Impostor replacement is Capgras.", "Incorrect. Cotard believes self or organs do not exist.", "Incorrect. Ekbom is delusional parasitosis."], "Wife swapped for double: Capgras."),
  mcq("bk2-psy-003", "Voices heard as real in external space without any stimulus present are classified as what?", ["Illusions", "True hallucinations", "Pseudohallucinations", "Afterimages"], 1, "True hallucinations lack stimulus yet carry full perceptual force in external objective space without insight. Pseudohallucinations are located in inner space with insight retained; illusions misread real stimuli.", ["Incorrect. Illusions need a real stimulus misinterpreted.", "Correct. Stimulus free external perception is true hallucination.", "Incorrect. Pseudohallucination keeps insight and inner location.", "Incorrect. Afterimages are normal retinal phenomena."], "No stimulus, fully real, outside: true hallucination."),
  mcq("bk2-psy-004", "Predominantly visual hallucinations in an acutely unwell patient most strongly suggest what category?", ["Schizophrenia", "Organic (delirium, Lewy body, occipital) cause", "Mania", "Personality disorder"], 1, "Visual hallucinations flag organic states: delirium, dementia with Lewy bodies, occipital lesions, drug intoxication or withdrawal. Auditory hallucinations dominate primary psychoses instead.", ["Incorrect. Schizophrenia hallucinates mainly in auditory modality.", "Correct. Visual means organic until disproven.", "Incorrect. Manic hallucinations are usually auditory and mood congruent.", "Incorrect. Personality disorder does not produce true visual hallucinations."], "Seeing things means search the body and brain."),
  mcq("bk2-psy-005", "Thought broadcasting, insertion and withdrawal belong historically to which symptom group?", ["Bleuler fundamental symptoms", "Schneider first rank symptoms", "Negative symptoms", "Catatonic signs"], 1, "Schneider listed passivity and thought alienation phenomena (insertion, withdrawal, broadcasting), third person voices and delusional perception as first rank for schizophrenia, though they occur in other psychoses too.", ["Incorrect. Bleuler emphasised association loosening, autism, ambivalence, affect.", "Correct. First rank Schneider symptoms.", "Incorrect. Negative symptoms are deficits like avolition.", "Incorrect. Catatonia is motor syndrome."], "Thoughts inserted or broadcast: Schneider first rank."),
  mcq("bk2-psy-006", "Speech that answers questions only after excessive irrelevant detail, eventually reaching the point, shows what?", ["Tangentiality", "Circumstantiality", "Word salad", "Flight of ideas"], 1, "Circumstantial speech over includes detail but reaches its goal; tangential speech never returns to the point. Word salad is incoherent; flight of ideas is rapid pressured topic shifting with links, typical of mania.", ["Incorrect. Tangentiality never reaches the answer.", "Correct. Long way round but arrives: circumstantial.", "Incorrect. Word salad lacks comprehensible links.", "Incorrect. Flight is pressured and rapid with distractibility."], "Arrives late with baggage: circumstantial."),
  mcq("bk2-psy-007", "Feeling insects crawling under skin (formication) classically accompanies which state?", ["Cocaine intoxication and alcohol withdrawal states", "Depression", "Dementia praecox only", "Obsessive compulsive disorder"], 0, "Tactile formication accompanies stimulant use (cocaine bugs) and delirium tremens spectrum states. It differs from Ekbom delusional infestation belief without true tactile perception context.", ["Correct. Stimulant and withdrawal states cause formication.", "Incorrect. Depression hallucinates rarely and mood congruently.", "Incorrect. Outdated term, not specific association.", "Incorrect. OCD has intrusive thoughts, not formication."], "Crawling skin: think stimulants or withdrawal."),
  mcq("bk2-psy-008", "Which symptom group best predicts long term functional outcome in schizophrenia?", ["Grandiose delusions", "Negative symptoms (avolition, alogia, flattening)", "Auditory hallucinations", "Persecutory themes"], 1, "Deficit (negative) symptoms correlate with poor social and occupational outcome and respond poorly to antipsychotics, whereas positive symptoms fluctuate and treat better. Rehabilitation targets negative burden.", ["Incorrect. Grandiosity fluctuates with episodes.", "Correct. Negative symptoms predict disability.", "Incorrect. Hallucinations treat relatively better.", "Incorrect. Persecution theme does not grade outcome."], "It is the missing drive, not voices, that disables."),
  mcq("bk2-psy-009", "Hypnopompic hallucinations occur at what transition and signify what?", ["Mid sleep pathology", "Waking from sleep; usually normal", "Entering sleep only; psychosis", "During seizures"], 1, "Hypnopompic (on waking) and hypnagogic (on falling asleep) imagery are normal sleep border phenomena, also prominent in narcolepsy. They do not diagnose psychosis in isolation.", ["Incorrect. They occur at sleep wake borders.", "Correct. On waking, normally benign.", "Incorrect. Sleep onset is hypnagogic; neither alone means psychosis.", "Incorrect. Seizure phenomena differ in stereotypy and consciousness."], "Half awake visions are usually normal."),
  mcq("bk2-psy-010", "A normal perception suddenly given delusional significance (a traffic light turning red means he is chosen) is termed what?", ["Secondary delusion", "Delusional perception", "Illusion", "Overvalued idea"], 1, "Delusional perception (Schneider first rank) attaches abnormal self referential significance to an accurately perceived stimulus in one step. Secondary delusions instead elaborate understandably from prior psychopathology.", ["Incorrect. Secondary delusions derive from other symptoms understandably.", "Correct. Instant delusional meaning on true perception.", "Incorrect. Illusion misperceives the stimulus itself.", "Incorrect. Overvalued ideas develop comprehensibly from personality."], "Seen correctly, meant delusionally: delusional perception.")]);

add("psy-schizophrenia", "Schizophrenia", "schizophrenia_overview", "Schizophrenia",
 ["Schizophrenia", "Positive and negative symptoms", "Dopamine hypothesis", "Antipsychotics"],
 [step("**Schizophrenia** is a psychotic disorder of perception, belief, thought form, motivation and cognition typically beginning in late adolescence or early adulthood, with men earlier than women. Diagnosis needs characteristic psychotic symptoms with functional decline over at least six months (DSM pattern) after excluding mood psychosis, substances and medical causes. No single symptom is pathognomonic; Schneider first rank symptoms occur but are not exclusive.", "Schizophrenia starts young, lasts months, impairs function. No single symptom proves it; exclude mood, drugs and disease first."),
  step("**Positive symptoms** (delusions, hallucinations, disorganisation) reflect excess or distortion of normal function and respond best to dopamine blockade. **Negative symptoms** (flattening, alogia, avolition, anhedonia, asociality) reflect lost function, dominate long term disability and respond poorly. Cognitive impairment in memory, executive function and processing speed is core and present from first episode, driving educational failure.", "Positive symptoms add distortions and treat well. Negative and cognitive deficits disable and treat poorly."),
  step("The **dopamine hypothesis** in modern form proposes presynaptic striatal dopamine excess driving positive symptoms (aberrant salience), with cortical dopamine and glutamate NMDA hypofunction contributing negative and cognitive features. All effective antipsychotics block D2 receptors; clozapine's superior efficacy in resistance remains partly unexplained. Neurodevelopmental origins (obstetric complications, adolescent synaptic pruning, cannabis and stress interaction) precede symptoms by years with prodromal social withdrawal.", "Too much striatal dopamine drives positive symptoms. Antipsychotics block D2. Development goes off track years before psychosis."),
  step("Antipsychotics are first line, chosen by side effect profile (local formulary), continued at least one to two years after first episode to prevent relapse, and switched after adequate failed trials. **Clozapine** is mandatory after two failed antipsychotics (treatment resistance) with blood monitoring for agranulocytosis. Long acting injections aid covert nonadherence. Psychosocial care (family intervention, supported employment, CBT for psychosis) halves relapse beyond drugs alone, and physical health monitoring counters the 15 to 20 year mortality gap.", "Keep antipsychotics years after first episode. Two failures earn clozapine. Family and work support halve relapses.", tbl(["Domain", "Features", "Drug response"], [["Positive", "Delusions, hallucinations, disorganisation", "Good D2 blockade response"], ["Negative", "Avolition, alogia, flattening, anhedonia", "Poor; rehabilitation focus"], ["Cognitive", "Memory, executive, speed deficits", "Poor; remediation research"], ["Affective", "Depression, suicide risk about 5 percent lifetime", "Treat comorbidity directly"]]))],
 ["Six month course with functional decline (DSM pattern)", "Clozapine after two failed antipsychotics, with blood monitoring", "Negative and cognitive symptoms drive disability", "Relapse prevention needs continuation 1 to 2 years after first episode"],
 "Genetic and neurodevelopmental vulnerability interacts with adolescent pruning, cannabis, migration and urban stress to produce striatal presynaptic dopamine dysregulation, with glutamatergic cortical dysfunction underlying cognitive and negative features.",
 ["Schizophrenia versus schizoaffective (mood episode overlap rule)", "Schizophrenia versus brief psychotic and delusional disorders by duration and symptoms", "Primary negative symptoms versus depression, parkinsonism and positive symptom withdrawal"],
 ["Structured diagnostic interview and collateral timeline", "Substance screen, medical exclusion labs and imaging when indicated", "Baseline metabolic, ECG and prolactin checks before antipsychotics"],
 [mcq("bk2-psy-011", "Minimum illness duration for schizophrenia in DSM pattern (including prodrome and residual) is what?", ["1 month", "6 months", "2 years", "2 weeks"], 1, "DSM requires six months of disturbance with at least one month of active phase symptoms (or less if treated). One month alone fits brief or schizophreniform categories by duration.", ["Incorrect. One month active phase sits inside longer course.", "Correct. Six months total disturbance.", "Incorrect. Two years was older chronicity notions.", "Incorrect. Two weeks is too brief for any primary psychosis label."], "Schizophrenia thinks in six months."),
  mcq("bk2-psy-012", "After failure of two adequate antipsychotic trials, the indicated drug is what?", ["Third typical antipsychotic", "Clozapine", "Lithium", "ECT first"], 1, "Treatment resistant schizophrenia (two adequate trials) mandates clozapine offer with haematological monitoring; delay worsens outcomes. ECT augments clozapine resistance later in specialist care.", ["Incorrect. Rotating similar D2 blockers repeats failure.", "Correct. Clozapine for treatment resistance.", "Incorrect. Lithium treats mania, not resistant psychosis core.", "Incorrect. ECT is adjunct after clozapine pathways."], "Two strikes and clozapine comes in."),
  mcq("bk2-psy-013", "All currently effective antipsychotics share which core pharmacology?", ["Serotonin reuptake blockade", "Dopamine D2 receptor blockade or partial agonism", "NMDA agonism", "GABA potentiation"], 1, "D2 antagonism (or partial agonism at D2) is the common antipsychotic mechanism correlating with positive symptom control; atypicality adds serotonergic and other actions modifying side effects.", ["Incorrect. That is antidepressant action.", "Correct. D2 blockade or partial agonism.", "Incorrect. NMDA agonism is pro psychotic direction research.", "Incorrect. GABA drugs sedate and treat anxiety or seizures."], "No D2 action, no antipsychotic."),
  mcq("bk2-psy-014", "Which feature most separates schizophrenia from delusional disorder?", ["Presence of any delusion", "Prominent hallucinations, disorganisation or negative symptoms with functional decline", "Age over 40", "Persecutory theme"], 1, "Delusional disorder keeps encapsulated delusions with otherwise preserved function and minimal hallucinations; schizophrenia adds broader psychopathology and marked functional deterioration.", ["Incorrect. Both share delusions.", "Correct. Breadth of symptoms plus decline defines schizophrenia.", "Incorrect. Age overlaps both diagnoses.", "Incorrect. Persecution occurs in both."], "One encapsulated belief versus whole mind illness."),
  mcq("bk2-psy-015", "Clozapine requires blood monitoring primarily because of which risk?", ["Agranulocytosis (neutropenia)", "Thrombocytosis", "Haemolysis", "Polycythaemia"], 0, "Clozapine can cause severe neutropenia and agranulocytosis (about 1 percent spectrum), mandating scheduled full blood counts with stop rules, plus vigilance for myocarditis and severe constipation.", ["Correct. Neutropenia monitoring is mandatory.", "Incorrect. Platelet excess is not the monitored danger.", "Incorrect. Haemolysis is not clozapine signature.", "Incorrect. Red cell excess is unrelated."], "Clozapine watches white cells."),
  mcq("bk2-psy-016", "Prodromal schizophrenia most typically shows what presentation?", ["Acute mania", "Social withdrawal, declining function and attenuated psychotic symptoms in adolescence", "Dementia", "Panic attacks only"], 1, "Attenuated psychosis syndrome with withdrawal, school decline, suspicion and perceptual oddities precedes frank psychosis in many, though most prodromal clinic attendees do not convert, requiring careful non stigmatising follow up.", ["Incorrect. Mania is mood episode presentation.", "Correct. Withdrawal plus attenuated symptoms in youth.", "Incorrect. Dementia is late life cognitive disease.", "Incorrect. Panic alone lacks attenuated psychosis."], "Quiet withdrawal before loud psychosis."),
  mcq("bk2-psy-017", "Lifetime suicide mortality in schizophrenia is approximately what and peaks when?", ["Under 0.1 percent, late life", "About 5 percent, early illness and post discharge", "50 percent, chronic stage", "Equal all decades"], 1, "Around 5 percent die by suicide, risk highest early in illness, after discharge and with depressive symptoms, insight and prior attempts. Vigilance in early psychosis services targets this window.", ["Incorrect. Risk is substantial, not negligible.", "Correct. About 5 percent, early peak.", "Incorrect. Half is far too high.", "Incorrect. Risk clusters early, not evenly."], "Early psychosis carries the suicide peak."),
  mcq("bk2-psy-018", "Long acting injectable antipsychotics principally solve which problem?", ["Treatment resistance", "Covert nonadherence and relapse from missed doses", "Negative symptoms", "Tardive dyskinesia"], 1, "Depot formulations make adherence transparent and steady levels, cutting relapse and hospitalisation where missed oral doses drive recurrence. They do not change drug efficacy molecule itself.", ["Incorrect. Resistance needs clozapine pathway.", "Correct. Adherence transparency and relapse prevention.", "Incorrect. Negative symptoms persist despite route.", "Incorrect. Movement risks remain drug dependent."], "Depots expose missed doses, they do not add potency."),
  mcq("bk2-psy-019", "Cannabis use in adolescence interacts with schizophrenia risk how?", ["Protective effect", "Increases risk, especially high potency daily use and genetic vulnerability", "No association", "Only causes brief intoxication"], 1, "Daily high potency cannabis in adolescence multiplies psychosis risk several fold in vulnerable individuals and advances onset; cessation advice is core early psychosis care. Association shows dose response and temporality.", ["Incorrect. Evidence points opposite.", "Correct. Dose dependent risk increase in vulnerable youth.", "Incorrect. Replicated association exists.", "Incorrect. Lasting risk beyond intoxication is demonstrated."], "Strong daily cannabis in teens feeds psychosis risk."),
  mcq("bk2-psy-020", "Catatonia in schizophrenia spectrum (and mood disorders) first line treatment is what?", ["Antipsychotic escalation", "Benzodiazepine (lorazepam) challenge then ECT if needed", "Antidepressant", "Restraint"], 1, "Catatonia (stupor, waxy flexibility, negativism, posturing) responds to lorazepam challenge in most, with ECT definitive for refractory or malignant forms. Antipsychotics can worsen catatonia and trigger neuroleptic malignant overlap.", ["Incorrect. Antipsychotics may worsen catatonia.", "Correct. Lorazepam first, ECT if refractory.", "Incorrect. Antidepressants do not unlock catatonia.", "Incorrect. Restraint is safety last resort, not treatment."], "Frozen patient: lorazepam melts, ECT rescues.")]);

add("psy-other-psychoses", "Other psychotic disorders", "other_psychotic_disorders", "Other Psychotic Disorders",
 ["Brief psychotic disorder", "Schizophreniform", "Delusional disorder", "Schizoaffective disorder"],
 [step("Psychotic disorders separate mainly by **duration, symptom breadth and mood overlap**. Brief psychotic disorder erupts suddenly with delusions, hallucinations or disorganisation lasting days to under one month with full return to baseline, often after marked stress. Schizophreniform disorder looks identical to schizophrenia but runs one to six months, reserving schizophrenia label for longer courses.", "Days of psychosis recovering fully is brief disorder. One to six months schizophrenia like is schizophreniform."),
  step("**Delusional disorder** sustains one or more delusions for at least a month with otherwise near normal functioning, minimal hallucinations (if present, tied to delusional theme) and no prior schizophrenia picture. Themes include erotomanic (another loves them), grandiose, jealous (Othello), persecutory and somatic (Ekbom infestation). Behaviour is rational outside the delusional system, making engagement and risk assessment (jealousy violence, stalking in erotomania) central.", "One encapsulated delusion, life otherwise intact: delusional disorder. Jealous and erotomanic types carry risk to others."),
  step("**Schizoaffective disorder** requires a major mood episode concurrent with active psychosis for most of illness, plus at least two weeks of delusions or hallucinations without mood symptoms, proving psychosis independence. It splits bipolar and depressive types. Diagnostic reliability is low and longitudinal review often revises it toward schizophrenia or bipolar disorder, so timelines from collateral sources decide more than cross sectional impressions.", "Mood plus psychosis most of time, but psychosis alone for two weeks: schizoaffective. Timelines overrule snapshots."),
  step("Secondary psychoses must always be excluded: substances (stimulants, cannabis, steroids, withdrawal), delirium, dementia, temporal lobe epilepsy, autoimmune encephalitis (anti NMDA receptor with ovarian teratoma in young women), thyroid and other endocrine disease, and postpartum psychosis which is usually bipolar spectrum emergency. New psychosis after 40, visual hallucinations, confusion or neurological signs demand medical workup before primary psychiatric labelling.", "Late, visual, confused or neurological psychosis is medical until disproven. Postpartum psychosis is an emergency.", tbl(["Disorder","Duration","Hallmark"], [["Brief psychotic", "Days to under 1 month", "Sudden, stress, full recovery"], ["Schizophreniform", "1 to 6 months", "Schizophrenia picture, shorter"], ["Schizophrenia", "6 months plus", "Broad symptoms, decline"], ["Delusional disorder", "1 month plus delusions", "Encapsulated, function kept"]]))],
 ["Duration ladder: brief under 1 mo, schizophreniform 1 to 6, schizophrenia 6 plus", "Schizoaffective needs 2 weeks psychosis without mood", "Delusional disorder preserves function outside delusion", "Postpartum psychosis is bipolar spectrum emergency"],
 "Shared psychosis vulnerability expresses by course modifiers: stress precipitated brief episodes remit fully, mood circuitry dominance produces schizoaffective overlap, and encapsulated delusions reflect focal belief fixation with preserved cognition.",
 ["Brief psychotic versus delirium (fluctuating consciousness)", "Delusional jealousy versus justified suspicion (evidence review)", "Schizoaffective versus bipolar with psychotic features (psychosis only in mood episodes)"],
 ["Longitudinal timeline from records and family", "Drug screen, autoimmune and metabolic workup by flags", "Risk assessment for stalking, jealousy violence and postpartum safety"],
 [mcq("bk2-psy-021", "Psychosis lasting 10 days after severe stress with complete recovery is classified as what?", ["Schizophrenia", "Brief psychotic disorder", "Delusional disorder", "Schizophreniform"], 1, "Brief psychotic disorder lasts at least a day and under a month with eventual full return to premorbid function, often stress precipitated. Longer courses move up the duration ladder.", ["Incorrect. Schizophrenia needs six months.", "Correct. Brief psychotic disorder under one month.", "Incorrect. Delusional disorder needs month plus encapsulated delusions.", "Incorrect. Schizophreniform runs one to six months."], "Ten days then well equals brief psychosis."),
  mcq("bk2-psy-022", "Schizoaffective disorder requires psychosis without mood symptoms for at least how long?", ["Never, psychosis only with mood", "Two weeks", "Six months", "One year"], 1, "Two weeks of delusions or hallucinations in absence of major mood episode prove independent psychosis within an illness otherwise dominated by concurrent mood and psychosis. Without it, diagnosis is mood disorder with psychotic features.", ["Incorrect. That pattern is psychotic mood disorder.", "Correct. Two mood free psychotic weeks required.", "Incorrect. Six months is schizophrenia duration.", "Incorrect. Year is not the criterion."], "Two lone psychotic weeks make schizoaffective."),
  mcq("bk2-psy-023", "Man convinced his wife is unfaithful, checking phones and following her, otherwise working normally, likely has which delusional type and key risk?", ["Erotomanic; risk of gifts", "Jealous (Othello); risk of violence to partner", "Somatic; risk of surgery seeking", "Grandiose; risk of spending"], 1, "Delusional jealousy (Othello syndrome) drives surveillance and confrontation with recognised risk of partner violence, needing risk assessment and safeguarding alongside treatment. Function outside belief stays preserved.", ["Incorrect. Erotomania believes another loves the patient.", "Correct. Jealous delusion with partner violence risk.", "Incorrect. Somatic concerns body disease or infestation.", "Incorrect. Grandiosity inflates status or powers."], "Othello delusion endangers the accused partner."),
  mcq("bk2-psy-024", "Young woman with new psychosis, seizures, autonomic instability and ovarian teratoma suggests which cause?", ["Schizophrenia", "Anti NMDA receptor encephalitis", "Brief psychosis", "Conversion disorder"], 1, "Autoimmune anti NMDA receptor encephalitis mimics first episode psychosis then adds dyskinesias, seizures and dysautonomia, associated with ovarian teratoma in young women; immunotherapy and tumour removal treat it.", ["Incorrect. Primary psychosis lacks this neurological cascade.", "Correct. Anti NMDA encephalitis until excluded.", "Incorrect. Brief psychosis excludes medical causes first.", "Incorrect. Conversion does not cause dysautonomia and seizures."], "Psychosis plus seizures plus teratoma: autoimmune brain."),
  mcq("bk2-psy-025", "Postpartum psychosis management priority is what?", ["Reassure as baby blues", "Emergency psychiatric admission, usually mother and baby unit, treating as bipolar spectrum", "Antidepressant alone at home", "Wait six weeks"], 1, "Postpartum psychosis (about 1 to 2 per 1000 births) is a psychiatric emergency with infanticide and suicide risk, usually bipolar spectrum, needing urgent admission (specialist mother baby unit where available), antipsychotics, mood treatment and safeguarding. Baby blues are mild and self limiting by contrast.", ["Incorrect. Blues are tearful mild days, not psychosis.", "Correct. Emergency admission and bipolar spectrum treatment.", "Incorrect. Home antidepressant alone is unsafe and may worsen.", "Incorrect. Delay risks catastrophe."], "Postpartum psychosis admits today."),
  mcq("bk2-psy-026", "Delusional disorder differs from schizophrenia most by what?", ["Delusions are bizzare always", "Function preserved outside delusions, hallucinations not prominent", "Onset in adolescence always", "Negative symptoms dominate"], 1, "Patients work and relate normally apart from delusional ramifications; prominent hallucinations, disorganisation and negative symptoms point instead to schizophrenia.", ["Incorrect. Delusions may be non bizarre (plausible themes).", "Correct. Preserved function, quiet other domains.", "Incorrect. Onset is often middle age.", "Incorrect. Negative dominance is schizophrenia deficit pattern."], "Normal life wrapped around one fixed belief."),
  mcq("bk2-psy-027", "Schizophreniform disorder is diagnosed when schizophrenia like illness lasts how long?", ["Under 1 month", "1 to 6 months", "Over 2 years", "Exactly lifelong"], 1, "One to six months of schizophrenia picture without yet meeting six month schizophrenia duration is schizophreniform; many later reclassify as schizophrenia if course extends.", ["Incorrect. Under month is brief psychotic.", "Correct. One to six months schizophreniform.", "Incorrect. Two years exceeds schizophrenia threshold already.", "Incorrect. Duration defines category, not lifetime guarantee."], "Too long for brief, too short for schizophrenia: schizophreniform."),
  mcq("bk2-psy-028", "Erotomanic delusion (de Clerambault) consists of belief that what?", ["Partner is unfaithful", "Another person, often higher status, is in love with the patient", "Body is infested", "Thoughts are broadcast"], 1, "Erotomania fixes on a usually unattainable love object, interpreting neutral acts as secret signals, with stalking risk. Jealousy, infestation and broadcasting belong to other phenomena.", ["Incorrect. That is jealous type.", "Correct. Beloved higher status admirer is erotomania.", "Incorrect. Infestation is somatic Ekbom.", "Incorrect. Broadcasting is first rank symptom."], "Secret famous lover means erotomania."),
  mcq("bk2-psy-029", "First psychosis at age 55 with visual hallucinations and fluctuating confusion first requires what?", ["Immediate schizophrenia diagnosis", "Medical and delirium workup before primary psychosis label", "Long term depot", "Psychotherapy alone"], 1, "Late onset, visual modality and fluctuation are red flags for delirium, dementia, Parkinson spectrum, substances and medical disease; investigation precedes primary psychotic disorder diagnosis.", ["Incorrect. Age and signs argue secondary cause.", "Correct. Exclude medical causes first.", "Incorrect. Depot commits before diagnosis known.", "Incorrect. Therapy does not investigate confusion."], "Old, visual and fluctuating: work up the body."),
  mcq("bk2-psy-030", "Shared psychotic disorder (folie a deux) is characterised by what?", ["Two unrelated patients same ward", "Delusion transmitted from dominant ill person to close dependent associate, improving on separation", "Twin concordance genetics", "Mass social media belief"], 1, "Induced delusional disorder develops in close associate of a primarily psychotic dominant person and often remits when separated, while treating the inducer. It is now classified under delusional disorders spectrum.", ["Incorrect. Coincidence is not induction.", "Correct. Transmitted delusion remitting on separation.", "Incorrect. Concordance is genetic epidemiology.", "Incorrect. Cultural beliefs shared widely are not folie a deux."], "Borrowed delusion fades apart.")]);

add("psy-suicide", "Suicide and deliberate self-harm", "suicide_and_self_harm", "Suicide and Deliberate Self-Harm",
 ["Suicide risk assessment", "Self-harm", "Means restriction", "Safety planning"],
 [step("**Suicide** is self inflicted death with intent to die, while deliberate self-harm includes self poisoning and self injury regardless of suicidal intent, though repetition strongly predicts later suicide. Most who die by suicide have a treatable mental disorder (depression, bipolar, schizophrenia, substance use) compounded by hopelessness, though risk prediction in individuals remains statistically poor: risk factors stratify groups, they do not predict persons, so care rests on formulation and modifiable needs, not scores alone.", "Self harm and suicide overlap but differ in intent. Scores cannot predict a person: formulate needs and treat illness."),
  step("Assessment explores ideation (passive death wish versus active plans), intent, **means access**, preparatory acts, past attempts (especially high lethality or violent methods), hopelessness, reasons for living, substance intoxication, psychosis commanding harm, recent losses, discharge or service transitions, and protective relationships. Asking directly about suicide does not implant the idea and is mandatory after self-harm. Collateral and records correct minimisation.", "Ask plainly: thoughts, plans, means, past acts, hope, protection. Asking does not plant suicide."),
  step("Highest risk periods are the weeks after psychiatric discharge, after self-harm presentations, and in early psychosis and severe depression with agitation, insomnia and alcohol use. Men die more often (lethal methods), women attempt more often. Older men, single or bereaved status, chronic pain and illness, unemployment and access to firearms, pesticides or high places form recurring exam patterns. Previous attempt is the strongest single predictor of future death.", "Weeks after discharge are deadliest. A past attempt predicts future death strongest."),
  step("Management treats underlying illness vigorously (antidepressants with follow up, lithium in bipolar disorder and clozapine in schizophrenia both reduce suicide specifically), restricts means (medication quantities, firearm and pesticide access, bridge barriers), builds collaborative **safety plans** (warning signs, internal coping, contacts, professional help, means safety), ensures rapid post discharge follow up within days, and involves family with consent. Compulsory admission applies when legal criteria of risk and disorder meet, as last resort therapeutic frame, not prediction proof.", "Treat illness, remove means, plan safety, follow up in days. Lithium and clozapine cut suicide specifically.", tbl(["Factor type", "Examples", "Modifiable?"], [["Static", "Past attempt, sex, age, family history", "No: stratifies vigilance"], ["Clinical dynamic", "Hopelessness, agitation, intoxication, insomnia", "Yes: treat now"], ["Situational", "Discharge week, loss, means access", "Yes: follow up, restrict means"], ["Protective", "Children, faith, relationships, future plans", "Strengthen in safety plan"]]))],
 ["Previous attempt is strongest predictor of suicide death", "Post discharge weeks carry highest risk; follow up within days", "Lithium (bipolar) and clozapine (schizophrenia) reduce suicide specifically", "Asking about suicide does not increase risk"],
 "Hopelessness and perceived burdensomeness with acquired capability through repeated pain or fear exposure convert ideation to action, while impulsivity, intoxication and means availability determine lethality of the moment.",
 ["Suicidal intent versus non suicidal self injury by function (relief, communication, intent)", "High risk formulation versus low actuarial score misuse", "Baby blues versus postpartum psychosis suicide and infanticide risk"],
 ["Direct ideation, plan, means and intent interview plus collateral", "Depression, psychosis and substance severity scales as adjuncts", "Means access audit at home with family"],
 [mcq("bk2-psy-031", "Strongest single predictor of future suicide death is what?", ["Male sex", "Previous suicide attempt", "Unemployment", "Family history alone"], 1, "Prior attempt (especially recent or high lethality) outweighs demographic factors in predicting death, though most attempters still do not die, showing prediction limits requiring formulation based care.", ["Incorrect. Sex stratifies but weaker than attempt history.", "Correct. Previous attempt predicts strongest.", "Incorrect. Unemployment contributes modestly.", "Incorrect. Family history raises risk less than own attempt."], "They tried before predicts most."),
  mcq("bk2-psy-032", "Asking a depressed patient directly about suicidal thoughts does what to risk?", ["Plants the idea and raises risk", "Does not increase risk and is essential assessment", "Is illegal without family present", "Only allowed after discharge"], 1, "Evidence and guidelines confirm direct enquiry does not induce suicide and uncovers treatable intent; avoidance misses plans and means needing intervention.", ["Incorrect. Myth contradicted by evidence.", "Correct. Ask directly; it does not implant.", "Incorrect. No such legal bar exists.", "Incorrect. Assessment belongs at presentation, not after."], "Asking saves, never plants."),
  mcq("bk2-psy-033", "Which drug has specific anti suicidal evidence in bipolar disorder?", ["Carbamazepine", "Lithium", "Valproate equally proven", "Lamotrigine"], 1, "Lithium reduces suicide and all cause mortality in bipolar disorder beyond mood stabilisation in meta analyses, influencing drug choice in high risk patients with adherence and monitoring capacity.", ["Incorrect. Carbamazepine lacks this evidence.", "Correct. Lithium anti suicidal effect.", "Incorrect. Valproate evidence is weaker and inconsistent.", "Incorrect. Lamotrigine prevents depression relapse without proven suicide reduction."], "Lithium guards bipolar lives doubly."),
  mcq("bk2-psy-034", "In schizophrenia, which antipsychotic is licensed to reduce recurrent suicidal behaviour?", ["Haloperidol", "Clozapine", "Aripiprazole", "Olanzapine"], 1, "Clozapine reduced suicidal behaviour in the InterSePT trial population with schizophrenia at high risk, an indication beyond treatment resistance, with its monitoring burden accepted for this benefit.", ["Incorrect. Haloperidol has no such indication.", "Correct. Clozapine anti suicidal indication in schizophrenia.", "Incorrect. Aripiprazole lacks this trial evidence.", "Incorrect. Olanzapine was comparator, not winner."], "Clozapine also shields against suicide in schizophrenia."),
  mcq("bk2-psy-035", "Highest risk interval after psychiatric inpatient discharge is what?", ["First days to weeks", "After one year", "Risk falls immediately to baseline", "Only at anniversaries"], 0, "Suicide rates spike in first week and month post discharge (transition, illness persisting, support gap), mandating follow up within days, crisis contacts and means safety before leave.", ["Correct. Days to weeks after discharge peak.", "Incorrect. Year later risk is lower.", "Incorrect. Discharge does not normalise risk instantly.", "Incorrect. Anniversaries are minor beside transitions."], "The week home is the danger week."),
  mcq("bk2-psy-036", "A collaborative safety plan differs from a no suicide contract how?", ["Contract guarantees safety legally", "Safety plan lists warning signs, coping steps, contacts and means restriction; contracts are ineffective and not recommended", "Both identical", "Safety plan is compulsory admission"], 1, "Stanley and Brown safety planning is an evidence based prioritised coping list made with the patient; no harm contracts lack evidence, may falsely reassure clinicians and are discouraged.", ["Incorrect. Contracts guarantee nothing.", "Correct. Concrete safety plan, not contract.", "Incorrect. They differ fundamentally in evidence.", "Incorrect. Safety planning is voluntary collaboration."], "Plan steps, never paper promises."),
  mcq("bk2-psy-037", "Means restriction reduces suicide because of which principle?", ["Suicidal crises are often brief and method substitution is incomplete", "It treats depression directly", "It removes all ideation", "It is punitive deterrence"], 0, "Many attempts are impulsive during short crises; blocking lethal means (barriers, pack sizes, firearm storage) lets crises pass and substitution to equally lethal methods is incomplete, lowering population deaths.", ["Correct. Brief crises plus incomplete substitution saves lives.", "Incorrect. It is environmental, not antidepressant.", "Incorrect. Ideation may persist while deaths fall.", "Incorrect. It is compassionate engineering, not punishment."], "Put time and distance between urge and lethal means."),
  mcq("bk2-psy-038", "After deliberate self poisoning, guideline care before discharge includes what?", ["Immediate discharge if medically fit", "Psychosocial assessment by trained staff for every presentation", "Police interview first", "No assessment if first time"], 1, "Every self-harm presentation warrants biopsychosocial assessment (intent, mental state, needs, risk formulation) before discharge regardless of medical clearance or repetition status, per NICE pattern guidance.", ["Incorrect. Medical fitness alone misses psychiatric need.", "Correct. Psychosocial assessment for all.", "Incorrect. Police role is not clinical assessment substitute.", "Incorrect. First presentations also predict future risk."], "Medically clear is not assessment done."),
  mcq("bk2-psy-039", "Which presentation pattern most raises concern for imminent risk in interview?", ["Passive wish to be dead, strong family support, no plans", "Detailed plan, means acquired, farewell acts, hopelessness and intoxication", "Chronic thoughts for years with coping plan", "Fleeting thought after argument, regretful"], 1, "Specific planning, acquired means, preparatory or farewell behaviour, hopelessness and disinhibiting intoxication together formulate high imminent risk needing urgent intervention, though no checklist replaces judgement.", ["Incorrect. Lower concern pattern with protection.", "Correct. Plan plus means plus preparation plus hopelessness.", "Incorrect. Chronic managed ideation differs in imminence.", "Incorrect. Transient regretted thought is lower acuity."], "Plan, means and goodbyes together alarm most."),
  mcq("bk2-psy-040", "Repetition of self-harm after an index episode occurs in roughly what proportion within a year, guiding follow up intensity?", ["About 1 percent", "About 15 to 20 percent, with suicide risk many fold population rate", "Over 90 percent", "Never studied"], 1, "Roughly one in six repeat within a year and suicide risk after self-harm is tens of times general population, justifying assertive follow up, therapy (DBT, CBT based) and safety planning for all.", ["Incorrect. Far higher than one percent.", "Correct. Fifteen to twenty percent repeat.", "Incorrect. Most do not repeat in a year.", "Incorrect. Extensively studied epidemiology."], "One in six repeat; follow them closely.")]);

add("psy-anxiety", "Anxiety disorders", "anxiety_disorders", "Anxiety Disorders",
 ["Generalised anxiety disorder", "Panic disorder", "Phobias", "CBT"],
 [step("**Anxiety disorders** share excessive fear or worry with avoidance and bodily arousal, separated by trigger and time course. Generalised anxiety disorder worries freely across domains for months with tension, fatigue, poor concentration and sleep disturbance. Panic disorder suffers recurrent unexpected panic attacks (minutes of palpitations, breathlessness, chest pain, derealisation and fear of dying) plus persistent fear of further attacks and avoidance.", "Free floating months of worry is GAD. Sudden minutes of terror with body storm is panic."),
  step("**Phobias** cue immediate fear to specific objects or situations (animals, blood injury, heights, flying) with avoidance out of proportion to danger; blood injury phobia uniquely faints via vasovagal diphasic response, treated with applied tension rather than pure relaxation. Social anxiety fears scrutiny and embarrassment, blushing and avoidance of performance, beginning in adolescence and impairing education and work. Agoraphobia fears places where escape feels difficult (crowds, transport, outside alone), often but not always after panic.", "Specific triggers mean phobia. Blood phobia faints, so tense muscles instead of relaxing. Social anxiety fears being judged."),
  step("First line treatment for most anxiety disorders is **CBT** (psychoeducation, cognitive restructuring, graded exposure, panic interoceptive exposure, worry scheduling), with SSRIs first line pharmacologically and pregabalin or buspirone in selected GAD patterns per local guidance. Benzodiazepines are short crisis adjuncts only, given dependence, falls and interference with exposure learning. Beta blockers help peripheral performance symptoms occasionally, not core anxiety disorders.", "Therapy plus SSRI treats anxiety durably. Benzodiazepines only briefly: they block exposure learning and addict."),
  step("Medical mimics must be screened by pattern: hyperthyroidism, pheochromocytoma spells, hypoglycaemia, arrhythmia and asthma drugs, caffeine and stimulant use, alcohol and benzodiazepine withdrawal. Anxiety with weight loss, tremor and heat intolerance needs thyroid tests; episodic headache, sweating and palpitations with hypertension spells raise pheochromocytoma. Treating mimics cures the anxiety label.", "Anxious plus thin, trembling and heat hating needs thyroid checked. Headache spells with pressure surges suggest pheochromocytoma.", tbl(["Disorder", "Core trigger", "First line anchor"], [["GAD", "Free floating multi domain worry", "CBT plus SSRI"], ["Panic disorder", "Unexpected attacks, fear of attacks", "CBT with interoceptive exposure, SSRI"], ["Social anxiety", "Scrutiny and embarrassment", "CBT exposure, SSRI"], ["Specific phobia", "Single object or situation", "Graded exposure alone usually"]]))],
 ["Benzodiazepines short term only in anxiety care", "Blood injury phobia faints: applied tension technique", "Panic peaks in minutes, GAD worries for months", "Screen thyroid in new anxiety with systemic signs"],
 "Threat circuitry (amygdala, insula) over detects danger while prefrontal regulation and safety learning lag; avoidance prevents extinction, maintaining disorders until exposure relearns safety.",
 ["GAD versus depression (worry future versus rumination past overlap)", "Panic attack versus ACS or PE (medical exclusion by risk)", "Social anxiety versus avoidant personality (episode versus lifelong pattern)"],
 ["Thyroid function, ECG and glucose when indicated", "Structured anxiety scales (GAD 7 adjunct)", "Substance and caffeine history"],
 [mcq("bk2-psy-041", "Excessive worry across many domains most days for 8 months with tension and insomnia best fits what?", ["Panic disorder", "Generalised anxiety disorder", "Specific phobia", "Adjustment disorder only"], 1, "GAD requires months (DSM six) of difficult to control multi topic worry with somatic tension symptoms. Panic is episodic attacks; phobia is cued; adjustment follows stressor within shorter frame.", ["Incorrect. Panic attacks are discrete surges.", "Correct. Chronic free floating worry is GAD.", "Incorrect. Phobia needs specific cue.", "Incorrect. Duration and breadth exceed adjustment pattern."], "Worrying about everything for months equals GAD."),
  mcq("bk2-psy-042", "Recurrent unexpected panic attacks plus persistent fear of more attacks and avoiding buses defines what?", ["GAD alone", "Panic disorder with agoraphobic avoidance", "Social anxiety", "OCD"], 1, "Panic disorder centres on unexpected attacks and anticipatory anxiety with avoidance that can generalise to agoraphobia. Interoceptive exposure and SSRIs form core treatment.", ["Incorrect. GAD worries without discrete unexpected attacks focus.", "Correct. Panic disorder with avoidance.", "Incorrect. Social fear is scrutiny based.", "Incorrect. Obsessions drive compulsions, not panic avoidance."], "Fear of the next attack is the disorder."),
  mcq("bk2-psy-043", "Blood injury phobia uniquely requires which treatment adaptation and why?", ["Pure relaxation; lowers pressure further", "Applied tension; prevents vasovagal faint", "Beta blockade; stops faints", "Avoid all exposure"], 1, "Diphasic vasovagal response drops blood pressure causing syncope, so tensing muscles during exposure maintains pressure. Other phobias use relaxation compatible exposure.", ["Incorrect. Relaxation worsens hypotensive faint.", "Correct. Applied tension prevents fainting.", "Incorrect. Beta blockers do not treat vasovagal phobia mechanism.", "Incorrect. Exposure remains essential."], "Blood phobia: tense, do not relax."),
  mcq("bk2-psy-044", "First line drug class for panic disorder and GAD when medication is indicated is what?", ["Benzodiazepines long term", "SSRIs", "Antipsychotics", "Tricyclics for all"], 1, "SSRIs (with CBT) are first line maintenance for panic and GAD, started low in panic sensitivity. Benzodiazepines suit brief crisis only due to dependence and exposure interference.", ["Incorrect. Long term benzodiazepines addict and block learning.", "Correct. SSRIs first line.", "Incorrect. Antipsychotics are not anxiety first line.", "Incorrect. Tricyclics work but side effects demote them."], "SSRI plus therapy, not endless benzodiazepines."),
  mcq("bk2-psy-045", "New anxiety with weight loss, tremor, heat intolerance and lid lag needs which test first?", ["Brain MRI", "Thyroid function tests", "EEG", "Colon cancer screen"], 1, "Hyperthyroidism mimics anxiety with adrenergic systemic signs; TFTs are cheap and decisive. Imaging follows only with focal or refractory clues.", ["Incorrect. No focal neurology described.", "Correct. Check thyroid function.", "Incorrect. EEG suits episodic altered awareness.", "Incorrect. Unrelated screening here."], "Anxious and thyrotoxic look alike: test TSH."),
  mcq("bk2-psy-046", "Episodic headache, palpitations, sweating and paroxysmal hypertension spells suggest which mimic?", ["Hypothyroidism", "Phaeochromocytoma", "Anaemia", "Vitamin D deficiency"], 1, "Catecholamine surges from phaeochromocytoma produce spell like anxiety with headache, sweating, palpitations and pressure spikes, confirmed by metanephrines. It is rare but classic and curable.", ["Incorrect. Hypothyroidism slows and cools.", "Correct. Phaeochromocytoma spells.", "Incorrect. Anaemia causes fatigue and pallor pattern.", "Incorrect. Vitamin deficiency lacks spells."], "Anxiety in hypertensive spells: hunt catecholamines."),
  mcq("bk2-psy-047", "Graded exposure therapy works in phobia by which learning principle?", ["Punishment", "Extinction or inhibitory safety learning through non reinforced feared contact", "Flooding memory erasure", "Sedation"], 1, "Repeated feared contact without catastrophe builds competing safety memory (inhibitory learning) reducing avoidance; escape during exposure undermines it, explaining benzodiazepine interference.", ["Incorrect. Punishment is not mechanism.", "Correct. Safety learning through exposure.", "Incorrect. Old fear memory persists but is inhibited.", "Incorrect. Sedation can impede learning."], "Stay until brain learns safe."),
  mcq("bk2-psy-048", "Teen avoiding presentations, blushing and fearing humiliation most likely has what?", ["Specific phobia", "Social anxiety disorder", "Panic disorder only", "Selective mutism adult type"], 1, "Social anxiety fears negative evaluation in social or performance situations from adolescence, impairing schooling. Treatment is CBT with social exposure plus SSRI when moderate severe.", ["Incorrect. No single object cue.", "Correct. Social anxiety disorder.", "Incorrect. Attacks are scrutiny cued, not unexpected.", "Incorrect. Mutism is childhood speech pattern."], "Fear of being judged is social anxiety."),
  mcq("bk2-psy-049", "Why are benzodiazepines avoided as long term anxiety treatment?", ["They never sedate", "Dependence, tolerance, falls, cognitive harm and blocking exposure learning", "They cause psychosis routinely", "They are illegal"], 1, "Chronic use produces physiological dependence with withdrawal anxiety mimicking illness, impairs memory and balance, and prevents extinction learning in CBT, so guidelines limit to short crisis courses.", ["Incorrect. Sedation is their main acute effect.", "Correct. Dependence and learning blockade.", "Incorrect. Psychosis is not routine effect.", "Incorrect. They remain legal controlled medicines."], "Short rescue only; chronic benzos trap anxiety."),
  mcq("bk2-psy-050", "Panic attack chest pain assessment principle is what?", ["Always attribute to panic in known patients", "Exclude cardiac and pulmonary emergencies by risk assessment first presentations and atypical features", "Give benzodiazepine and discharge immediately", "No ECG ever needed"], 1, "Panic mimics ACS, PE and arrhythmia; first or atypical attacks need medical triage (history, ECG, troponin by protocol) before psychiatric attribution, even in anxious patients who also develop heart disease.", ["Incorrect. Known panic patients still infarct.", "Correct. Rule out emergencies appropriately.", "Incorrect. Sedation without triage is unsafe.", "Incorrect. ECG is core chest pain triage."], "Panic is diagnosis after chest is cleared.")]);

add("psy-stress-trauma", "Trauma and stressor-related disorders", "trauma_stressor_disorders", "Trauma and Stressor-Related Disorders",
 ["PTSD", "Acute stress disorder", "Adjustment disorder", "Trauma focused CBT"],
 [step("Exposure to actual or threatened death, serious injury or sexual violence (directly, witnessed, learned of in close others, or repeated occupational exposure) can produce trauma disorders separated by time and symptom pattern. **Acute stress disorder** runs three days to one month with intrusion, dissociation, avoidance and arousal. **PTSD** persists beyond one month across four clusters: intrusion (flashbacks, nightmares), avoidance, negative cognition and mood, and hyperarousal (hypervigilance, exaggerated startle, insomnia).", "Under a month is acute stress; beyond a month with four clusters is PTSD. Flashbacks plus avoidance plus vigilance is the signature."),
  step("**Adjustment disorder** is emotional or behavioural symptoms within three months of an identifiable stressor, out of proportion or impairing, resolving within six months after stressor ends, and not better explained by another disorder or normal bereavement. It is a common exam distractor against major depression: if full major depressive episode criteria are met, depression is diagnosed instead. Subtypes specify anxious, depressed or conduct features.", "Stressor linked distress not meeting bigger diagnoses is adjustment disorder. Full depression criteria outrank it."),
  step("Trauma focused psychological therapy is first line for PTSD: **trauma focused CBT** and **EMDR** (eye movement desensitisation and reprocessing) have strongest evidence, offered after stabilisation without mandatory single session debriefing, which is ineffective and potentially harmful when forced. SSRIs (sertraline, paroxetine class examples) or venlafaxine are second line or adjuncts; prazosin nightmares evidence is mixed. Benzodiazepines worsen outcomes and are avoided.", "Trauma focused CBT or EMDR first. Never force single session debriefing. Avoid benzodiazepines in PTSD."),
  step("Complex PTSD (ICD pattern) adds disturbances in self organisation (affect dysregulation, negative self concept, relational difficulty) after prolonged or repeated trauma like childhood abuse or captivity, needing phase based care (safety and stabilisation, trauma processing, reintegration). Children present with re enactment play, regression and somatic complaints. Comorbid depression, substance use and traumatic brain injury must be co treated, and safeguarding current safety precedes trauma processing always.", "Prolonged trauma adds self and relationship damage: complex PTSD. Safety first, then processing, then rebuilding.", tbl(["Disorder","Timing","Defining edge"], [["Acute stress disorder", "3 days to 1 month", "Dissociation prominent"], ["PTSD", "Over 1 month", "Four clusters persist"], ["Adjustment disorder", "Within 3 months of stressor", "Subthreshold, stressor bound"], ["Complex PTSD", "Prolonged trauma, any duration after", "Self organisation disturbed"]]))],
 ["PTSD needs over one month; acute stress is 3 days to 1 month", "Trauma focused CBT and EMDR are first line", "Single session forced debriefing is harmful and not offered", "Full major depression outranks adjustment disorder"],
 "Conditioned fear memory with impaired extinction and contextualisation (hippocampal) plus amygdala hyperreactivity and noradrenergic hyperarousal maintain re experiencing and vigilance; avoidance prevents corrective learning.",
 ["PTSD versus depression (intrusion and avoidance versus pure anhedonia)", "Adjustment versus normal grief (function and symptom pattern)", "Acute stress versus PTSD by calendar only"],
 ["Trauma history with safety and safeguarding screen", "PTSD symptom scales (PCL pattern) as adjuncts", "Substance, depression and TBI comorbidity assessment"],
 [mcq("bk2-psy-051", "PTSD can be diagnosed when symptoms persist beyond what duration after trauma?", ["3 days", "1 month", "1 week", "6 months minimum"], 1, "Beyond one month separates PTSD from acute stress disorder (3 days to 1 month). Six months is schizophrenia timeframe distractor.", ["Incorrect. Three days starts acute stress window.", "Correct. Over one month is PTSD.", "Incorrect. One week remains acute stress.", "Incorrect. Six months not required."], "One month line divides acute stress from PTSD."),
  mcq("bk2-psy-052", "First line treatment for PTSD in adults is what?", ["Benzodiazepines", "Trauma focused CBT or EMDR", "Antipsychotics", "Forced debriefing next day"], 1, "Trauma focused CBT and EMDR carry strongest guideline support. Drugs are adjunct or second line; benzodiazepines may worsen course and forced debriefing is discouraged.", ["Incorrect. Benzodiazepines worsen PTSD outcomes.", "Correct. Trauma focused therapy first.", "Incorrect. Antipsychotics only for specific comorbidity.", "Incorrect. Debriefing is ineffective or harmful."], "Process trauma in therapy; do not sedate or force recount."),
  mcq("bk2-psy-053", "Soldier with flashbacks, nightmares, avoiding fireworks, emotional numbness and exaggerated startle 8 months after combat shows which PTSD clusters?", ["Only intrusion", "All four: intrusion, avoidance, negative mood cognition, hyperarousal", "Mania clusters", "Negative symptoms only"], 1, "The vignette spans intrusion (flashbacks, nightmares), avoidance, negative alterations (numbness) and arousal (startle), fulfilling PTSD pattern beyond one month.", ["Incorrect. Symptoms exceed intrusion alone.", "Correct. All four clusters present.", "Incorrect. No elevated mood or pressure.", "Incorrect. Arousal and intrusion are not negative symptoms."], "Four clusters, one diagnosis: PTSD."),
  mcq("bk2-psy-054", "Distress 2 months after divorce, tearful and anxious, not meeting depression criteria, resolving as stressor settles, best fits what?", ["Major depression", "Adjustment disorder with mixed anxiety and depressed mood", "PTSD", "Persistent depressive disorder"], 1, "Adjustment disorder follows identifiable stressor within three months, is out of proportion or impairing yet subthreshold for major disorders, and remits within six months of stressor termination.", ["Incorrect. Full criteria explicitly not met.", "Correct. Adjustment disorder pattern.", "Incorrect. No qualifying trauma or intrusion clusters.", "Incorrect. Needs two years chronic low mood."], "Stressor bound and subthreshold equals adjustment."),
  mcq("bk2-psy-055", "Single session psychological debriefing forced after trauma is recommended how?", ["Mandatory within 24 hours", "Not recommended; may worsen outcomes", "Only for children", "Replaces trauma therapy"], 1, "Trials show compulsory single session debriefing does not prevent PTSD and can increase symptoms by forced re exposure without therapeutic structure; watchful waiting and targeted therapy for persistent symptoms replace it.", ["Incorrect. Mandating is against evidence.", "Correct. Avoid forced debriefing.", "Incorrect. Children also not forced.", "Incorrect. It never substitutes therapy."], "Do not make everyone relive it once."),
  mcq("bk2-psy-056", "Complex PTSD adds which features beyond core PTSD?", ["Psychosis", "Affect dysregulation, negative self concept and relational disturbance", "Mania", "Amnesia for trauma always"], 1, "ICD complex PTSD includes disturbances in self organisation after prolonged trauma: emotional dysregulation, shame based negative self view and inability to feel close to others, guiding phase based treatment.", ["Incorrect. Psychosis is not defining addition.", "Correct. Self organisation disturbance defines complex form.", "Incorrect. Mood elevation unrelated.", "Incorrect. Amnesia is dissociative feature, not required."], "Core PTSD plus broken self and relationships equals complex."),
  mcq("bk2-psy-057", "Which drug strategy is guideline supported when PTSD pharmacotherapy is needed?", ["Prazosin guaranteed for nightmares", "SSRI (or venlafaxine) as adjunct or second line", "Benzodiazepine nightly long term", "Antipsychotic monotherapy"], 1, "Sertraline and paroxetine class SSRIs and venlafaxine show modest PTSD efficacy as adjuncts when therapy unavailable, declined or insufficient. Prazosin nightmare data are inconsistent after large trials.", ["Incorrect. Large trial failed to confirm prazosin benefit.", "Correct. SSRI or venlafaxine second line.", "Incorrect. Benzodiazepines harm course.", "Incorrect. Antipsychotics lack monotherapy support."], "Drugs support therapy in PTSD, never sedatives."),
  mcq("bk2-psy-058", "Child after abuse re enacts events repetitively in play, wets bed again and complains of stomach aches. This presentation suggests what?", ["Normal play only", "Age appropriate expression of post traumatic stress", "Schizophrenia", "Autism regression"], 1, "Children express PTSD through traumatic play re enactment, developmental regression and somatic symptoms rather than verbal flashback reports, needing trauma focused CBT adapted for children and caregiver work.", ["Incorrect. Pattern follows trauma with regression.", "Correct. Childhood PTSD expression.", "Incorrect. No psychotic phenomena described.", "Incorrect. Regression here is trauma linked, not neurodevelopmental course."], "Children play out trauma they cannot narrate."),
  mcq("bk2-psy-059", "Before trauma processing therapy begins, the essential first phase is what?", ["Immediate detailed recounting", "Safety, stabilisation and coping skills, especially in complex trauma", "Medication washout", "Hypnosis"], 1, "Phase based care establishes current safety (ongoing abuse excluded), stabilisation and regulation skills before memory processing, preventing overwhelm and dropout, then reintegration follows.", ["Incorrect. Recounting without safety destabilises.", "Correct. Safety and stabilisation first.", "Incorrect. Medicines continue as indicated.", "Incorrect. Hypnosis is not required phase."], "Safe and steady before story."),
  mcq("bk2-psy-060", "Bereavement with yearning, waves of grief tied to reminders, preserved capacity for positive memories, most likely represents what?", ["Major depression always", "Normal grief, not adjustment or depressive disorder by itself", "PTSD", "Prolonged grief in all cases"], 1, "Normal grief comes in reminder linked waves with preserved self esteem and positive recall, differing from persistent anhedonia and worthlessness of depression. Prolonged grief disorder needs prolonged intense impairment beyond cultural norms (months thresholds vary).", ["Incorrect. Grief waves alone are not depression.", "Correct. Normal grief pattern.", "Incorrect. No trauma intrusion cluster required.", "Incorrect. Most grief is not prolonged disorder."], "Grief waves with warmth preserved are human, not illness.")]);

add("psy-dissociative-somatic", "Dissociative and somatic symptom disorders", "dissociative_somatic_disorders", "Dissociative and Somatic Symptom Disorders",
 ["Somatic symptom disorder", "Functional neurological disorder", "Dissociative amnesia", "Illness anxiety"],
 [step("**Somatic symptom disorder** is diagnosed by distressing somatic symptoms plus excessive thoughts, anxiety and behaviours devoted to them for over six months, not by absence of medical explanation alone. Patients may have genuine disease; the disorder is the disproportionate response consuming life. Management validates symptoms as real, schedules regular brief reviews, limits investigations to red flags, treats comorbid anxiety and depression, and uses CBT to reduce checking and catastrophic interpretation.", "Real symptoms plus excessive worry and checking for months is somatic symptom disorder. Validate, schedule reviews, stop endless testing."),
  step("**Illness anxiety disorder** fears having serious disease with minimal symptoms and compulsive checking or avoidance of care. Conversion disorder, now **functional neurological symptom disorder**, presents with voluntary motor or sensory loss (weakness, non epileptic seizures, blindness, gait disorder) incompatible with anatomy, with positive signs like Hoover sign (hip extension normalises during contralateral flexion) and midline splitting of sensory loss. Diagnosis is rule in by positive signs, not merely normal scans.", "Functional weakness is ruled in by Hoover sign, not just normal MRI. Fear of disease with few symptoms is illness anxiety."),
  step("**Dissociative disorders** disrupt identity, memory and consciousness usually after trauma: dissociative amnesia (inability to recall autobiographical, often traumatic, information beyond ordinary forgetting, sometimes with fugue travel), depersonalisation derealisation disorder (persistent feeling detached from self or world unreal, with intact reality testing), and dissociative identity disorder (two or more identity states with amnesia gaps, controversial and trauma linked, specialist diagnosis only). Dissociative seizures overlap functional neurology and need video EEG when uncertain.", "Detached from self is depersonalisation; world unreal is derealisation; lost autobiographical memory is dissociative amnesia. Reality testing stays intact."),
  step("Factitious disorder (imposed on self or another) falsifies or induces illness for sick role without external incentives, unlike malingering which fabricates for external gain (money, avoiding duty). Factitious imposed on another (formerly Munchausen by proxy) is a safeguarding emergency for the victim, often a child with puzzling presentations only with caregiver. Management is non confrontational, single coordinating team, minimal invasive tests and safeguarding referral, never accusation theatre.", "Sick role without reward is factitious; money or escape motive is malingering. Factitious on a child means safeguard now.", tbl(["Condition", "Core driver", "External gain"], [["Somatic symptom disorder", "Excessive symptom focus", "Not required; distress genuine"], ["Factitious disorder", "Assume sick role", "Absent by definition"], ["Malingering", "Fabricated symptoms", "Present: money, avoidance"], ["Functional disorder", "Involuntary functional symptoms", "Not deliberate production"]]))],
 ["Functional diagnosis uses positive signs (Hoover), not normal tests alone", "Somatic symptom disorder can coexist with real disease", "Depersonalisation keeps intact reality testing", "Factitious on another is safeguarding emergency"],
 "Stress and attention amplify symptom perception through predictive brain processing, while dissociation compartmentalises traumatic memory and identity; functional symptoms reflect reversible network dysfunction without structural lesion.",
 ["Functional weakness versus stroke (positive signs, pattern)", "Somatic symptom versus undiagnosed disease (red flag vigilance)", "Dissociative amnesia versus dementia (autobiographical, abrupt, trauma)"],
 ["Focused examination for positive functional signs", "Video EEG for dissociative seizures when indicated", "Limited targeted investigations by red flags, collateral and safeguarding where relevant"],
 [mcq("bk2-psy-061", "Hoover sign positive in leg weakness indicates what?", ["Stroke", "Functional weakness", "Myasthenia", "Cord compression"], 1, "Involuntary hip extension synergising with contralateral hip flexion reveals preserved power in functional weakness. It is a rule in positive sign, though organic disease must still be excluded appropriately.", ["Incorrect. Stroke weakness lacks this synergy pattern.", "Correct. Hoover sign means functional weakness.", "Incorrect. Myasthenia fatigues without Hoover pattern.", "Incorrect. Cord signs include sphincter and level findings."], "Leg extends when other flexes: functional."),
  mcq("bk2-psy-062", "Somatic symptom disorder diagnosis principally requires what?", ["No medical cause found ever", "Distressing symptoms plus excessive thoughts, feelings and behaviours about them over 6 months", "Deliberate faking", "Normal investigations"], 1, "DSM shifted from medically unexplained to maladaptive response: symptoms (explained or not) with disproportionate persistent thoughts, high health anxiety and excessive time or energy devoted, causing impairment.", ["Incorrect. Medical disease may coexist.", "Correct. Excessive response over six months.", "Incorrect. Faking defines factitious or malingering.", "Incorrect. Tests may be abnormal from comorbid disease."], "It is the excess worry, not missing cause."),
  mcq("bk2-psy-063", "Persistent feeling of being detached observer of oneself, world seems unreal, yet knows it is only a feeling. Diagnosis?", ["Psychosis", "Depersonalisation derealisation disorder", "Dissociative identity", "Dementia"], 1, "Depersonalisation (self detached) and derealisation (world unreal) with intact reality testing define this dissociative disorder, often anxiety and trauma linked, distinct from psychotic loss of insight.", ["Incorrect. Reality testing intact excludes psychosis.", "Correct. Depersonalisation derealisation disorder.", "Incorrect. No identity alteration with amnesia.", "Incorrect. Cognition otherwise preserved."], "Feels unreal but knows better: depersonalisation."),
  mcq("bk2-psy-064", "Mother repeatedly brings child with fabricated apnoea episodes occurring only with her, investigations normal. This is what and needs what?", ["Malingering by child", "Factitious disorder imposed on another; safeguarding referral", "Somatic symptom in mother only", "Normal parenting"], 1, "Caregiver falsification (factitious imposed on another) abuses the victim through presentations and procedures; child protection referral and coordinated single team care are urgent, without direct accusatory confrontation.", ["Incorrect. Child is victim, not malingerer.", "Correct. Imposed factitious disorder, safeguard child.", "Incorrect. Victim focused abuse pattern dominates.", "Incorrect. Fabricated episodes are abuse."], "Fabricated child illness equals safeguard now."),
  mcq("bk2-psy-065", "Malingering is distinguished from factitious disorder by what?", ["Symptoms are unconscious", "External incentives drive intentional production", "Investigations are normal", "Onset is sudden"], 1, "Both intentionally produce symptoms, but malingering seeks external gain (compensation, avoiding work or prosecution) while factitious seeks internal sick role. Neither is diagnosed lightly; evidence must be strong.", ["Incorrect. Both are intentional by definition.", "Correct. External gain equals malingering.", "Incorrect. Normal tests occur in many conditions.", "Incorrect. Timing does not separate them."], "Money motive means malingering; sick role means factitious."),
  mcq("bk2-psy-066", "Non epileptic (dissociative) seizures are best confirmed how when diagnosis uncertain?", ["Normal routine EEG once", "Video EEG capturing typical event without epileptiform activity plus semiology", "MRI normal alone", "Response to benzodiazepine"], 1, "Capturing habitual event on video EEG (long duration, closed eyes, asynchronous movements supportive) without epileptic discharge is gold standard, though coexistence with epilepsy occurs and needs neurology psychiatry joint care.", ["Incorrect. Routine EEG misses events and interictal norms mislead.", "Correct. Video EEG of typical attack.", "Incorrect. MRI normality does not prove dissociation.", "Incorrect. Sedatives suppress many behaviours nonspecifically."], "Film the event with EEG running."),
  mcq("bk2-psy-067", "Man found wandering in another city unable to recall identity after traumatic event, later recovering memory, suggests what?", ["Dementia", "Dissociative amnesia with fugue", "Schizophrenia", "Delirium"], 1, "Dissociative fugue (amnesia subtype) involves purposeful travel with autobiographical amnesia following trauma, with recovery typical. Dementia is progressive and delirium fluctuates with inattention.", ["Incorrect. Dementia does not remit like this.", "Correct. Dissociative amnesia with fugue.", "Incorrect. No psychotic syndrome described.", "Incorrect. Consciousness clear, course different."], "Trauma, travel and lost identity: dissociative fugue."),
  mcq("bk2-psy-068", "Management anchor for somatic symptom disorder in primary care is what?", ["Order every requested test", "Regular scheduled reviews, validation, limited investigations and CBT, one coordinating clinician", "Tell patient nothing is wrong", "Rotate many specialists"], 1, "Scheduled (not symptom contingent) appointments, empathic validation, focus on function, restrained testing and CBT reduce doctor shopping and iatrogenesis. Dismissal destroys alliance and worsens symptoms.", ["Incorrect. Testing cascades harm.", "Correct. Scheduled coordinated care plus CBT.", "Incorrect. Symptoms are real suffering.", "Incorrect. Fragmentation amplifies anxiety."], "Book reviews by calendar, not by symptom panic."),
  mcq("bk2-psy-069", "Illness anxiety disorder differs from somatic symptom disorder chiefly how?", ["No anxiety present", "Preoccupation with having disease despite minimal or no somatic symptoms", "Symptoms are faked", "Duration under a week"], 1, "Illness anxiety centres on disease conviction with slight symptoms and checking or avoidance behaviours, while somatic symptom disorder centres on distressing prominent symptoms themselves. Both need CBT and restrained reassurance testing.", ["Incorrect. Anxiety is defining.", "Correct. Disease fear with minimal symptoms.", "Incorrect. Faking is factitious spectrum.", "Incorrect. Needs six months pattern."], "Few symptoms, huge disease fear: illness anxiety."),
  mcq("bk2-psy-070", "Sensory loss splitting exactly at midline and stopping at joint lines suggests which pattern?", ["Dermatomal lesion", "Functional sensory loss", "Cord syndrome", "Peripheral neuropathy"], 1, "Non anatomical boundaries (exact midline split impossible from overlapping innervation, joint line cutoffs) indicate functional sensory loss, a positive pattern sign supporting functional neurological disorder alongside normal reflexes.", ["Incorrect. Dermatomes follow root maps.", "Correct. Midline split means functional pattern.", "Incorrect. Cord gives level and tract signs.", "Incorrect. Neuropathy is glove stocking gradual."], "Impossible anatomy points functional.")]);

add("psy-alcohol", "Alcohol use disorder", "alcohol_use_disorder", "Alcohol Use Disorder",
 ["Alcohol dependence", "Delirium tremens", "Wernicke encephalopathy", "Thiamine"],
 [step("**Alcohol use disorder** spans hazardous use, harmful use and dependence (ICD) or severity graded DSM disorder defined by craving, loss of control, tolerance, withdrawal, salience over life and continued use despite harm. Screening uses AUDIT (CAGE as crude bedside adjunct: Cut down, Annoyed, Guilty, Eye opener). Dependence physiology shows as morning drinking, relief drinking and withdrawal tremor, sweating, nausea, tachycardia, seizures and hallucinations on stopping.", "Craving, lost control, tolerance and morning relief drinking mean dependence. AUDIT screens better than CAGE."),
  step("**Withdrawal** timelines are examination favourites: tremor and autonomic hyperactivity within hours, withdrawal seizures at about 24 to 48 hours, alcoholic hallucinosis (clear consciousness auditory hallucinations) around 24 to 48 hours, and **delirium tremens** at 48 to 96 hours with fluctuating confusion, fever, severe autonomic storm and visual hallucinations carrying mortality without treatment. Benzodiazepine reducing regimens (chlordiazepoxide pattern) plus fluids and electrolytes treat withdrawal; carbamazepine is alternative in selected pathways.", "Seizures day one to two, delirium tremens day two to four. Benzodiazepines treat withdrawal; confusion plus fever plus storm is DT."),
  step("**Wernicke encephalopathy** (thiamine deficiency) classically triads confusion, ataxia and ophthalmoplegia or nystagmus, though full triad is minority, so any confused malnourished drinker gets parenteral thiamine before glucose (glucose without thiamine may precipitate it). Untreated it progresses to **Korsakoff syndrome**: irreversible anterograde amnesia with confabulation and relatively preserved other cognition. Pabrinex style parenteral replacement precedes oral thiamine in at risk refeeding patients.", "Confused ataxic drinker with eye signs: thiamine before glucose, parenteral. Korsakoff forgets new events and confabulates."),
  step("Relapse prevention combines psychosocial programmes (motivational interviewing, mutual aid, relapse prevention CBT) with drugs: **acamprosate** (supports abstinence, glutamate modulation, renal caution), **naltrexone** (opioid blockade reducing heavy drinking, liver and opioid interaction cautions) and disulfiram (supervised aversive aldehyde reaction, only in motivated abstinent patients with consent). Treat comorbid depression after abstinence reassessment, screen liver, pancreas, cancers and fetal alcohol spectrum in offspring.", "Acamprosate keeps abstinence, naltrexone cuts heavy drinking, disulfiram punishes drinking under supervision only.", tbl(["Withdrawal event", "Typical onset", "Consciousness"], [["Tremor, autonomic", "6 to 12 hours", "Clear"], ["Withdrawal seizure", "24 to 48 hours", "Brief post ictal"], ["Alcoholic hallucinosis", "24 to 48 hours", "Clear"], ["Delirium tremens", "48 to 96 hours", "Fluctuating confusion"]]))],
 ["Thiamine before glucose in at risk drinkers", "Delirium tremens at 48 to 96 hours kills untreated", "Acamprosate abstinence, naltrexone heavy drinking, disulfiram aversive", "Full Wernicke triad is minority: treat on suspicion"],
 "Chronic alcohol neuroadaptation down regulates GABA and up regulates glutamate, so cessation unleashes excitatory autonomic storm; thiamine dependent carbohydrate metabolism failure injures mammillary bodies and thalamus producing Wernicke Korsakoff lesions.",
 ["Delirium tremens versus alcoholic hallucinosis (consciousness)", "Korsakoff amnesia versus dementia (confabulation, isolated memory)", "Harmful use versus dependence (withdrawal and control)"],
 ["AUDIT score, withdrawal severity CIWA pattern monitoring", "Thiamine status clinically, liver panel, MCV, GGT adjuncts", "CT head when seizures focal or head injury suspected"],
 [mcq("bk2-psy-071", "Delirium tremens typically begins how long after last drink?", ["2 hours", "48 to 96 hours", "2 weeks", "Immediately"], 1, "DT emerges two to four days into withdrawal with delirium, fever and autonomic instability, distinct from early tremor and day one seizures. Untreated mortality historically high; benzodiazepines and supportive care treat it.", ["Incorrect. Two hours is intoxication or early tremor.", "Correct. Forty eight to ninety six hours.", "Incorrect. Two weeks is beyond withdrawal syndrome.", "Incorrect. Immediate is intoxication phase."], "Day three confused and stormy equals DT."),
  mcq("bk2-psy-072", "Before giving IV glucose to a malnourished dependent drinker, what must be given and why?", ["Insulin; prevent hyperglycaemia", "Parenteral thiamine; prevent precipitating Wernicke encephalopathy", "Antibiotics; sepsis", "Benzodiazepine only"], 1, "Glucose load consumes thiamine in metabolism and can precipitate or worsen Wernicke in deficient patients, so parenteral B vitamins precede or accompany glucose in at risk patients per local protocol.", ["Incorrect. Insulin follows glucose monitoring, not this rule.", "Correct. Thiamine before glucose.", "Incorrect. Sepsis treatment does not precede metabolically.", "Incorrect. Sedation treats withdrawal but not this metabolic trap."], "Thiamine first, glucose second."),
  mcq("bk2-psy-073", "Confusion, ataxia and nystagmus in a homeless drinker diagnose which emergency, and full triad frequency?", ["Korsakoff; triad always complete", "Wernicke encephalopathy; full triad present in minority", "Delirium tremens; always febrile", "Hepatic encephalopathy; asterixis required"], 1, "Wernicke presents variably: only minority show complete classic triad, so suspicion alone mandates immediate parenteral thiamine. Korsakoff is chronic amnesic aftermath, not acute eye sign stage.", ["Incorrect. Korsakoff is chronic amnesia, triad is Wernicke.", "Correct. Wernicke, treat without full triad.", "Incorrect. Fever and autonomic storm define DT differently.", "Incorrect. Hepatic flap differs and eye signs absent."], "Treat Wernicke on a hint, not full house."),
  mcq("bk2-psy-074", "Korsakoff syndrome core deficit is what?", ["Global dementia", "Anterograde amnesia with confabulation, other cognition relatively spared", "Aphasia", "Hemiparesis"], 1, "Diencephalic injury blocks new memory formation while remote memory and intellect relatively persist, filled gaps by plausible confabulation without intent to deceive. Rehabilitation uses memory aids and structured environments.", ["Incorrect. Deficit is strikingly memory selective.", "Correct. New learning lost, confabulation fills.", "Incorrect. Language otherwise intact.", "Incorrect. No focal motor lesion."], "Cannot lay new memories, invents to fill."),
  mcq("bk2-psy-075", "Auditory hallucinations in clear consciousness 36 hours after stopping alcohol, without confusion, indicate what?", ["Delirium tremens", "Alcoholic hallucinosis", "Schizophrenia onset", "Wernicke"], 1, "Hallucinosis in withdrawal window with clear sensorium (often derogatory voices) contrasts DT delirium with visual hallucinations and autonomic storm. It usually resolves days, occasionally persists.", ["Incorrect. DT clouds consciousness with fever.", "Correct. Clear consciousness hallucinosis.", "Incorrect. Timing and clarity point withdrawal state.", "Incorrect. Wernicke confuses with eye and gait signs."], "Clear mind hearing voices day two: hallucinosis."),
  mcq("bk2-psy-076", "Drug best matched to maintaining abstinence via anti craving glutamate modulation, dosed with meals, renal caution, is what?", ["Disulfiram", "Acamprosate", "Naltrexone", "Methadone"], 1, "Acamprosate supports abstinence after detoxification, started after withdrawal, renally cleared. Naltrexone reduces heavy drinking days; disulfiram is aversive; methadone treats opioid dependence.", ["Incorrect. Disulfiram punishes drinking via acetaldehyde.", "Correct. Acamprosate for abstinence support.", "Incorrect. Naltrexone opioid antagonist reduces reward.", "Incorrect. Methadone is opioid substitution."], "Acamprosate keeps the quit."),
  mcq("bk2-psy-077", "Patient on naltrexone for alcohol needs emergency opioid analgesia after trauma. Key issue is what?", ["No interaction", "Opioid blockade reduces analgesia; specialist pain plan needed, and naltrexone must stop before elective opioids", "Naltrexone potentiates opioids", "It causes DT"], 1, "Mu blockade blunts opioid analgesia and precipitates withdrawal in opioid dependent patients; elective surgery planning stops naltrexone in advance (oral days, injection weeks per guidance) and trauma needs anaesthetic led alternatives or high dose monitored opioids.", ["Incorrect. Interaction is major.", "Correct. Blockade complicates opioid analgesia.", "Incorrect. Opposite effect occurs.", "Incorrect. DT follows alcohol cessation, not naltrexone."], "Naltrexone blocks the morphine key."),
  mcq("bk2-psy-078", "CAGE screening questions stand for Cut down, Annoyed, Guilty and what?", ["Energy drinks", "Eye opener (morning drink)", "Eating less", "Exercise"], 1, "Eye opener (needing morning drink to steady nerves or cure hangover) signals dependence physiology. Two or more yes answers raise concern, though AUDIT quantifies better.", ["Incorrect. Not part of mnemonic.", "Correct. Eye opener morning drink.", "Incorrect. Appetite not in CAGE.", "Incorrect. Exercise unrelated."], "E is for eye opener."),
  mcq("bk2-psy-079", "Supervised disulfiram is appropriate only when patient is what?", ["Still drinking daily refusing abstinence", "Motivated, abstinent, fully informed and medically screened, with supervision", "Pregnant routinely", "Unaware in food"], 1, "Disulfiram requires abstinence goal, consent understanding reaction (flushing, vomiting, hypotension with alcohol including sauces and aftershave), cardiac and liver screening and supervised adherence; covert administration is unethical and dangerous.", ["Incorrect. Drinking on it is dangerous without intent.", "Correct. Motivated abstinent informed supervised.", "Incorrect. Avoid in pregnancy.", "Incorrect. Covert dosing is prohibited."], "Disulfiram only with knowing willing quitter."),
  mcq("bk2-psy-080", "Withdrawal seizure prophylaxis and treatment in dependent drinkers rely mainly on which drug class?", ["Antipsychotics", "Benzodiazepines cross tolerant with alcohol", "Antidepressants", "Opioids"], 1, "Benzodiazepines substitute GABAergic alcohol effect with taper preventing seizures and DT, dosed by fixed reducing or symptom triggered CIWA regimens. Antipsychotics lower seizure threshold and are adjuncts only for hallucinations with cover.", ["Incorrect. They may provoke seizures alone.", "Correct. Benzodiazepine taper is backbone.", "Incorrect. No withdrawal seizure protection.", "Incorrect. Opioids irrelevant and harmful."], "Replace alcohol GABA smoothly with benzodiazepine taper.")]);

add("psy-opioids", "Opioid use disorder", "opioid_use_disorder_psych", "Opioid Use Disorder",
 ["Opioid dependence", "Methadone", "Naloxone", "Opioid withdrawal"],
 [step("**Opioid use disorder** is compulsive opioid use despite harm driven by mu receptor reward, tolerance and a withdrawal syndrome of dysphoria, lacrimation, rhinorrhoea, piloerection, mydriasis, diarrhoea, cramps and insomnia that is miserable but rarely medically dangerous in healthy adults (unlike alcohol withdrawal). Overdose kills by respiratory depression with miosis and reduced consciousness, reversed by **naloxone** titrated to ventilation, remembering its short half life against long acting opioids needs infusion or observation.", "Opioid withdrawal tortures but rarely kills; overdose kills by stopped breathing. Naloxone wears off before long opioids do."),
  step("Opioid substitution therapy with **methadone** (full agonist, supervised daily dosing initially, QT prolongation and accumulation cautions) or **buprenorphine** (partial agonist with ceiling on respiratory depression, sublingual, can precipitate withdrawal if started while full agonist occupies receptors) halves mortality, crime and HIV transmission. Treatment retention matters more than dose purity debates; psychosocial support and take home phases follow stability criteria in local programmes.", "Methadone full agonist supervised; buprenorphine partial with safety ceiling but can precipitate withdrawal if mistimed. Staying in treatment halves deaths."),
  step("Prescribing safety threads through all care: avoid co prescribed benzodiazepines and alcohol (overdose synergy), rotate and taper chronic pain opioids by function goals, supply take home naloxone to patients and families, and treat neonatal opioid withdrawal in exposed infants supportively with scoring guided therapy. Needle exchange, HIV and hepatitis testing and vaccination, wound and endocarditis vigilance form harm reduction core.", "Never stack opioids with benzodiazepines casually. Hand out naloxone. Harm reduction keeps people alive until recovery."),
  step("Detoxification alone without maintenance has high relapse and **lost tolerance overdose** risk, so maintenance is default for moderate severe disorder. Naltrexone (oral or depot) suits highly motivated abstinent patients (detoxified at least a week) such as professionals in monitoring programmes. Pain in maintained patients still deserves analgesia: continue substitution, add multimodal and titrated short acting opioids with specialist input rather than withholding.", "Detox alone relapses and lost tolerance kills. Maintained patients still deserve real pain relief.", tbl(["Drug", "Receptor action", "Signature caution"], [["Methadone", "Full mu agonist", "QT prolongation, accumulation, supervised start"], ["Buprenorphine", "Partial mu agonist", "Precipitated withdrawal if induced early"], ["Naloxone", "Mu antagonist rescue", "Short half life: re sedation risk"], ["Naltrexone", "Mu antagonist maintenance", "Needs opioid free week, blocks analgesia"]]))],
 ["Naloxone duration shorter than most opioids: observe for re sedation", "Buprenorphine induction waits for mild withdrawal (COWS guided)", "Maintenance halves mortality; detox alone relapses", "Opioid plus benzodiazepine co use multiplies overdose"],
 "Mu receptor adaptation produces tolerance and opponent withdrawal physiology (noradrenergic rebound from locus coeruleus), while conditioned cues trigger craving long after detoxification, sustaining relapse without maintenance pharmacotherapy.",
 ["Opioid withdrawal versus alcohol withdrawal danger (autonomic seizures)", "Methadone versus buprenorphine by setting and risk", "Intoxication miosis versus withdrawal mydriasis"],
 ["Clinical opiate withdrawal scale (COWS) for induction timing", "ECG for methadone QT, urine toxicology with consent", "HIV, hepatitis B and C screening and overdose education"],
 [mcq("bk2-psy-081", "Opioid overdose triad requiring naloxone is what?", ["Mydriasis, tachycardia, diarrhoea", "Miosis, respiratory depression, reduced consciousness", "Fever, rigidity, confusion", "Tremor, seizures, hallucinations"], 1, "Pinpoint pupils, hypoventilation and coma define opioid toxicity; naloxone titrated to adequate breathing (not necessarily full alertness) reverses it. Withdrawal shows opposite dilated, hyperactive gut picture.", ["Incorrect. That is withdrawal physiology.", "Correct. Miosis, slow breathing, coma.", "Incorrect. Rigidity fever suggests serotonin or neuroleptic syndromes.", "Incorrect. Those are alcohol withdrawal events."], "Small pupils, slow breaths, out cold: naloxone."),
  mcq("bk2-psy-082", "Why observe after successful naloxone reversal of methadone overdose?", ["Naloxone causes seizures routinely", "Naloxone half life is shorter than methadone, causing re sedation", "Methadone converts to morphine", "Tolerance returns instantly"], 1, "Naloxone lasts roughly 30 to 90 minutes while methadone and modified release opioids persist many hours, so recurrence of respiratory depression needs observation and sometimes infusion.", ["Incorrect. Seizures are not naloxone routine effect.", "Correct. Short antidote versus long poison.", "Incorrect. No such conversion explains it.", "Incorrect. Tolerance dynamics differ."], "Antidote fades first: watch them breathe again."),
  mcq("bk2-psy-083", "Buprenorphine induction should start when patient shows what state and why?", ["Full intoxication; better absorption", "Mild to moderate withdrawal (COWS threshold); avoids precipitated withdrawal", "Immediately after methadone dose", "Only under anaesthesia"], 1, "High affinity partial agonist displaces full agonists; giving it while receptors are occupied plunges patients into precipitated withdrawal. Waiting for objective withdrawal signs (COWS guided) makes induction tolerable.", ["Incorrect. Intoxication occupancy maximises precipitation.", "Correct. Wait for mild withdrawal signs.", "Incorrect. Methadone occupancy is worst timing.", "Incorrect. Office induction is standard."], "Empty receptors first, then buprenorphine."),
  mcq("bk2-psy-084", "Methadone maintenance signature cardiac risk needing ECG vigilance is what?", ["QT prolongation and torsades", "Bradycardia only", "Heart block in all", "Pericarditis"], 0, "Methadone prolongs QT dose dependently (risk rises over 100 mg range and with interacting CYP drugs or hypokalaemia), so ECG at induction and dose changes follows local protocol.", ["Correct. QT prolongation with torsades risk.", "Incorrect. Bradycardia alone is not signature.", "Incorrect. Block is not universal effect.", "Incorrect. Pericarditis unrelated."], "Methadone stretches QT: check ECG."),
  mcq("bk2-psy-085", "Opioid withdrawal in healthy adults is best characterised how versus alcohol withdrawal?", ["Equally lethal with seizures", "Extremely distressing but rarely medically dangerous; alcohol withdrawal can kill", "Painless", "Causes delirium routinely"], 1, "Opioid withdrawal lacks seizures and delirium tremens equivalents; danger concentrates in dehydration vulnerability (pregnancy, comorbidity, neonates). Alcohol and benzodiazepine withdrawal are the lethal ones.", ["Incorrect. Seizures belong to GABA drug withdrawal.", "Correct. Miserable but rarely lethal; alcohol withdrawal kills.", "Incorrect. Withdrawal is intensely unpleasant.", "Incorrect. Consciousness stays clear."], "Opioid withdrawal tortures; alcohol withdrawal kills."),
  mcq("bk2-psy-086", "After detoxification without maintenance, the major cause of fatal relapse overdose is what?", ["Increased tolerance", "Lost tolerance meeting previously tolerated dose", "Liver failure", "Naloxone resistance"], 1, "Abstinence resets tolerance within weeks, so returning to old doses overwhelms respiration; this post detox and post prison window is among deadliest, motivating maintenance and naloxone provision.", ["Incorrect. Tolerance falls, not rises.", "Correct. Lost tolerance plus old dose kills.", "Incorrect. Liver not central mechanism.", "Incorrect. Naloxone still works if given."], "Clean weeks erase tolerance, old dose becomes lethal."),
  mcq("bk2-psy-087", "Naltrexone maintenance for opioid disorder requires what before starting?", ["Active daily use", "Opioid free interval (about 7 to 10 days) to avoid precipitated withdrawal", "Benzodiazepine cover", "Pregnancy"], 1, "Antagonist in occupied receptors precipitates severe withdrawal, so confirmed abstinence interval and negative challenge approaches precede oral or depot naltrexone in motivated patients.", ["Incorrect. Active use precipitates withdrawal.", "Correct. Week opioid free first.", "Incorrect. Sedatives do not enable induction.", "Incorrect. Pregnancy favours agonist maintenance."], "Antagonist last, after receptors empty a week."),
  mcq("bk2-psy-088", "In pregnancy with opioid use disorder, recommended pharmacotherapy is what?", ["Detoxification forced", "Methadone or buprenorphine maintenance", "Naltrexone first line", "No treatment"], 1, "Maintenance stabilises maternal levels, reduces relapse and illicit use, improving fetal outcomes despite neonatal withdrawal syndrome, which is treatable; detox relapse cycles harm more. Buprenorphine (often without naloxone combination per local practice) is alternative.", ["Incorrect. Forced detox relapses dangerously.", "Correct. Agonist maintenance in pregnancy.", "Incorrect. Antagonist data limited, not first line.", "Incorrect. Untreated disorder harms mother and fetus."], "Maintain the mother, treat the newborn."),
  mcq("bk2-psy-089", "Co prescribing which drug class most multiplies opioid overdose death?", ["SSRIs", "Benzodiazepines (and alcohol, gabapentinoids caution)", "Antihistamines", "Statins"], 1, "Sedative co depressants synergise respiratory depression; opioid benzodiazepine combinations carry boxed warnings, requiring taper of one or both, naloxone supply and documented rationale when unavoidable.", ["Incorrect. SSRIs interact modestly (tramadol serotonin caution).", "Correct. Benzodiazepines multiply overdose.", "Incorrect. Antihistamines sedate mildly less central.", "Incorrect. Statins irrelevant."], "Opioid plus benzo is the lethal stack."),
  mcq("bk2-psy-090", "Harm reduction services with proven mortality and infection benefit include what?", ["Needle exchange, naloxone distribution, substitution therapy and HIV hepatitis testing", "Abstinence lectures only", "Drug testing punishment", "Withholding vaccines"], 0, "Sterile equipment, take home naloxone, maintenance therapy and blood borne virus care reduce deaths and transmission without increasing use, forming evidence based public health core.", ["Correct. Proven harm reduction bundle.", "Incorrect. Lectures alone lack outcome evidence.", "Incorrect. Punitive testing deters care.", "Incorrect. Vaccination protects, withholding harms."], "Keep people alive and uninfected until recovery.")]);

add("psy-other-substances", "Cannabis, stimulants, nicotine and other substances", "other_substance_disorders", "Cannabis, Stimulants, Nicotine and Other Substances",
 ["Cannabis", "Cocaine and amphetamines", "Nicotine dependence", "Synthetic cannabinoids"],
 [step("**Cannabis** dependence shows craving, tolerance and withdrawal (irritability, insomnia, vivid dreams, appetite loss) peaking days after cessation in heavy users, while intoxication impairs driving and learning. High potency daily adolescent use multiplies psychosis risk and can precipitate schizophrenia in vulnerable youth; cannabis induced psychosis with persisting symptoms beyond intoxication needs psychosis pathway care. Cannabinoid hyperemesis syndrome (compulsive hot bathing relief) resolves with cessation.", "Heavy cannabis withdraws irritable and sleepless. Strong daily teen use feeds psychosis. Endless vomiting eased by hot showers is hyperemesis."),
  step("**Stimulants** (cocaine, amphetamines, methamphetamine) intoxicate with euphoria, mydriasis, tachycardia, hypertension, hyperthermia and bruxism, toxic with chest pain (coronary spasm), arrhythmia, seizures, rhabdomyolysis and excited delirium; benzodiazepines are first line for stimulant toxicity agitation and cardiovascular surge, avoiding pure beta blockade in cocaine chest pain dogma pathways per cardiology guidance. Withdrawal crashes with hypersomnia, hyperphagia and dysphoria, suicide vigilance needed. No approved substitution drug exists; contingency management has best evidence.", "Stimulant storm gets benzodiazepines. Crash afterwards risks suicide. No methadone equivalent exists; reward based therapy works best."),
  step("**Nicotine dependence** drives most preventable death via smoking diseases; brief advice plus pharmacotherapy (combination NRT patch plus short acting form, varenicline highest single agent quit rates via alpha4beta2 partial agonism, bupropion alternative) doubles or triples quit success. Varenicline neuropsychiatric fears were not confirmed in large safety trials. E cigarettes help some adult smokers quit when complete switching occurs, while never smokers (especially youth) should not start any nicotine.", "Patch plus gum beats single NRT. Varenicline quits most and is safer than feared. Help smokers switch fully or quit, never recruit youth."),
  step("Other substances fill patterns: MDMA (serotonin toxicity, hyponatraemia from water loading), hallucinogens (perceptual distortion, hallucinogen persisting perception), inhalants (sudden sniffing death arrhythmia, cognitive damage), GHB (steep dose response, severe withdrawal needing high dose benzodiazepines), synthetic cannabinoids (severe agitation and psychosis beyond natural cannabis), ketamine (ulcerative cystitis, dependence) and gabapentinoid misuse with opioids. Polysubstance use is the rule, so histories must inventory everything including prescribed and online drugs.", "Every drug history inventories all substances. Synthetics hit harder than natural versions; ketamine scars bladders.", tbl(["Substance", "Intoxication signature", "Withdrawal or harm signature"], [["Cocaine", "Mydriasis, chest pain, hyperthermia", "Crash dysphoria, no specific antidote drug"], ["Cannabis high potency", "Psychosis vulnerability, hyperemesis", "Irritability, insomnia days 2 to 6"], ["MDMA", "Serotonin syndrome, dilutional hyponatraemia", "Comedown low mood"], ["GHB", "Coma at small dose increments", "Severe delirium like alcohol withdrawal"]]))],
 ["Benzodiazepines first line for stimulant toxicity", "Varenicline most effective single quit drug", "Cannabinoid hyperemesis loves hot showers", "Contingency management best evidence in stimulant dependence"],
 "Dopamine transporter blockade or reversal floods synapses in stimulants, nicotinic receptor up regulation sustains smoking, and CB1 adaptation produces cannabis withdrawal, each reinforcing compulsive reuse through craving circuits.",
 ["Cannabis psychosis versus schizophrenia by persistence after abstinence", "Stimulant chest pain versus ACS (both: treat as ACS until cleared)", "Nicotine withdrawal versus depression relapse by timing"],
 ["Full polysubstance inventory and urine toxicology with consent", "ECG and troponin in stimulant chest pain", "Carbon monoxide verification in quit programmes"],
 [mcq("bk2-psy-091", "First line drug treatment for severe cocaine intoxication with agitation, hypertension and hyperthermia is what?", ["Beta blocker alone", "Benzodiazepines", "Antipsychotics alone first", "Flumazenil"], 1, "Benzodiazepines blunt central sympathetic outflow treating agitation, pressure, tachycardia and seizures together, with cooling and fluids. Pure beta blockade risks unopposed alpha effects dogma; antipsychotics add hyperthermia and QT burden as adjuncts only.", ["Incorrect. Unopposed alpha concern and no sedation.", "Correct. Benzodiazepines calm the storm source.", "Incorrect. Adjunct role, hyperthermia risk.", "Incorrect. Flumazenil precipitates seizures here."], "Stimulant storm: benzodiazepine umbrella."),
  mcq("bk2-psy-092", "Most effective single pharmacotherapy for smoking cessation on average is what?", ["Single nicotine patch alone", "Varenicline", "Willpower counselling only", "Bupropion in all smokers"], 1, "Varenicline partial agonism gives highest continuous abstinence among single agents, comparable to combination NRT; EAGLES trial reassured neuropsychiatric safety in stable psychiatric patients.", ["Incorrect. Single form NRT is less effective than combination.", "Correct. Varenicline leads single agents.", "Incorrect. Unaided quit rates are low.", "Incorrect. Bupropion helps but contraindications limit universality."], "Varenicline tops single quit drugs."),
  mcq("bk2-psy-093", "Cyclical vomiting in heavy cannabis user relieved by compulsive hot showers, normal workup, is what?", ["Cannabinoid hyperemesis syndrome", "Cannabis withdrawal only", "Gastroparesis diabetic", "Porphyria"], 0, "Hyperemesis syndrome follows prolonged heavy use, with hot bathing behaviour pathognomonic, resolving with sustained cessation (topical capsaicin and haloperidol are acute adjunct reports). Antiemetic cycles without cessation fail.", ["Correct. Cannabinoid hyperemesis syndrome.", "Incorrect. Withdrawal lacks this vomiting bathing pattern.", "Incorrect. Diabetic gastroparesis lacks cannabis bathing clues.", "Incorrect. Porphyria adds pain and neuropsychiatric pattern."], "Vomiting plus hot showers plus weed equals hyperemesis."),
  mcq("bk2-psy-094", "Methamphetamine dependence treatment with strongest evidence base is what?", ["Maintenance stimulant prescribing routinely", "Contingency management (reward based behavioural therapy)", "Antipsychotic long term", "Benzodiazepine maintenance"], 1, "No approved agonist substitution exists; contingency management and CBT show best abstinence outcomes. Antipsychotics treat stimulant psychosis episodes only.", ["Incorrect. Not standard approved care.", "Correct. Contingency management leads.", "Incorrect. Only for psychosis comorbidity.", "Incorrect. Sedative maintenance addicts without benefit."], "Reward abstinence, there is no stimulant methadone."),
  mcq("bk2-psy-095", "Cannabis withdrawal in heavy daily users typically peaks when and with what?", ["No withdrawal exists", "Days 2 to 6 with irritability, insomnia, vivid dreams and appetite loss", "One month later with seizures", "Within minutes with coma"], 1, "Recognised withdrawal syndrome emerges 24 to 72 hours, peaks first week, mostly resolving in two weeks; it is uncomfortable not dangerous, managed supportively. Seizures suggest other substances.", ["Incorrect. Withdrawal is DSM recognised.", "Correct. First week irritability and insomnia peak.", "Incorrect. Seizures not cannabis withdrawal feature.", "Incorrect. Coma suggests other intoxicants."], "Week one grumpy and sleepless after quitting weed."),
  mcq("bk2-psy-096", "MDMA toxicity deaths commonly involve which two mechanisms?", ["Hypothermia and hypoglycaemia", "Hyperthermia with serotonin toxicity and dilutional hyponatraemia from excess water", "Liver necrosis only", "Opioid respiratory depression"], 1, "Serotonergic hyperthermia with rhabdomyolysis and DIC plus SIADH and overhydration hyponatraemia causing cerebral oedema kill in club settings; cooling, benzodiazepines and careful fluids or hypertonic care by severity treat them.", ["Incorrect. Heat, not cold, dominates.", "Correct. Hyperthermia plus hyponatraemia.", "Incorrect. Liver injury is late different pattern.", "Incorrect. MDMA is stimulant serotonergic, not opioid."], "Hot and waterlogged: MDMA twin killers."),
  mcq("bk2-psy-097", "Ketamine chronic heavy use signature organ damage is what?", ["Pulmonary fibrosis", "Ulcerative cystitis and biliary tract dilatation", "Renal stones only", "Cardiomyopathy"], 1, "Ketamine cystitis scars and shrinks bladder with frequency, pain and haematuria, sometimes hydronephrosis; cessation early may reverse, late needs urology. Biliary dilatation and cognitive effects also reported.", ["Incorrect. Lungs not signature target.", "Correct. Bladder ulceration and shrinkage.", "Incorrect. Stones are not hallmark.", "Incorrect. Heart muscle not primary victim."], "Ketamine burns the bladder small."),
  mcq("bk2-psy-098", "Synthetic cannabinoid (spice) intoxication differs from natural cannabis typically how?", ["Milder and safer", "More severe agitation, psychosis, seizures and deaths from full CB1 agonism", "No psychoactivity", "Only sedation"], 1, "Synthetics are potent full agonists (natural THC partial) with contaminants, producing severe neuropsychiatric and medical toxicity unpredictable by dose, managed supportively with benzodiazepines.", ["Incorrect. Danger exceeds natural cannabis.", "Correct. Full agonism, severe toxicity.", "Incorrect. Strongly psychoactive.", "Incorrect. Agitation dominates, not sedation."], "Spice is cannabis chemistry without brakes."),
  mcq("bk2-psy-099", "Combination nicotine replacement means what strategy with what benefit?", ["Two patches doubled", "Long acting patch plus short acting gum or lozenge for cravings, higher quit than single form", "Patch only when craving", "NRT indefinitely at high dose for all"], 1, "Steady patch levels plus rescue short acting doses for breakthrough cravings outperforms single form and rivals varenicline; duration typically 8 to 12 weeks with taper individualised.", ["Incorrect. Double patch is not standard combination.", "Correct. Patch plus rescue form.", "Incorrect. Patch needs continuous wear.", "Incorrect. Indefinite high dose is not default."], "Patch for baseline, gum for breakthrough."),
  mcq("bk2-psy-100", "Inhalant (volatile substance) abuse most feared acute event is what?", ["Liver failure", "Sudden sniffing death from cardiac arrhythmia sensitised to catecholamines", "Psychosis chronic", "Blindness"], 1, "Hydrocarbons sensitise myocardium so fright or exertion adrenaline triggers fatal arrhythmia even first use; chronic use adds cognitive, renal and marrow toxicity (toluene leukoencephalopathy).", ["Incorrect. Liver not acute killer here.", "Correct. Sudden sniffing death arrhythmia.", "Incorrect. Psychosis less defining acute risk.", "Incorrect. Methanol, not typical inhalants, blinds."], "One sniff, adrenaline surge, heart stops.")]);

add("psy-delirium", "Delirium", "delirium_overview", "Delirium",
 ["Delirium", "Hyperactive hypoactive delirium", "CAM", "Antipsychotics delirium"],
 [step("**Delirium** is acute fluctuating disturbance of attention and awareness with cognitive change developing over hours to days from medical causes, distinct from dementia (chronic, attention preserved early) though delirium superimposed on dementia is commonest hospital reality. Hypoactive delirium (quiet, withdrawn, drowsy) is missed most and carries worst outcomes; hyperactive agitation draws attention; mixed forms fluctuate. Every delirium is medical emergency workup: infection, hypoxia, metabolic, drugs, withdrawal, pain, retention and intracranial causes via structured bundles (TIME, PINCH ME patterns).", "Acute confused and inattentive means delirium until cause found. Quiet hypoactive delirium kills most and is missed most."),
  step("Diagnosis uses **CAM** logic: acute fluctuating course plus inattention, plus either disorganised thinking or altered consciousness. Collateral history establishes baseline and acuity; examination seeks infection source, dehydration, drug culprits (anticholinergics, opioids, benzodiazepines), withdrawal states and focal neurology. Investigations follow clues: observations, glucose, bloods, cultures, ECG, imaging only with focal signs, trauma or failure to improve.", "CAM needs acute fluctuation plus inattention plus messy thinking or consciousness. History from family proves acuity."),
  step("Management treats causes, not just behaviour: **HELP** style multicomponent prevention (orientation, hydration, early mobilisation, sleep hygiene, glasses and hearing aids, pain control) prevents a third of hospital delirium. Antipsychotics do not shorten delirium generally and are reserved low dose short term for severe distress or danger unresponsive to de escalation (cautions in Parkinson and Lewy body where sensitivity can be lethal, favouring quetiapine class specialist choices or none). Benzodiazepines worsen delirium except alcohol or benzodiazepine withdrawal delirium where they are treatment. Restraint and catheters aggravate it.", "Prevent with orientation, water, movement, sleep and spectacles. Antipsychotics only for danger, never routine. Benzodiazepines worsen unless withdrawal."),
  step("Prognosis is grave beyond the ward: delirium multiplies mortality, institutionalisation and later dementia risk, so discharge needs cognitive follow up and family explanation that recovery can take weeks to months. Persistent delirium demands re hunt for occult infection, subdural, autoimmune or non convulsive seizures (EEG). Capacity fluctuates with delirium, so major decisions wait or use legal frameworks with reassessment.", "Delirium scars brains long term: survivors need cognitive follow up. Decisions wait for clear days where possible.", tbl(["Feature","Delirium","Dementia"], [["Onset", "Hours to days", "Years insidious"], ["Attention", "Impaired early, fluctuating", "Preserved early"], ["Consciousness", "Often altered", "Clear until late"], ["Course", "Fluctuates daily", "Steadily progressive"]]))],
 ["Attention deficit plus fluctuation defines delirium", "Hypoactive delirium is commonest missed and deadliest", "Antipsychotics reserved for severe danger, not routine delirium", "Benzodiazepines treat withdrawal delirium, worsen others"],
 "Multifactorial failure of attentional networks from systemic inflammation, metabolic derangement and anticholinergic or dopaminergic drug imbalance on a vulnerable (often demented, sensory impaired) brain.",
 ["Delirium versus dementia versus depression (pseudodementia attention)", "Hyperactive delirium versus mania or psychosis (acuity, attention)", "Lewy body fluctuation versus delirium superimposed"],
 ["Collateral baseline and CAM or 4AT assessment", "Sepsis and metabolic screen, medication review", "EEG for non convulsive status when unexplained persistence"],
 [mcq("bk2-psy-101", "Core diagnostic feature separating delirium from dementia at presentation is what?", ["Memory loss severity", "Impaired attention with acute fluctuating course", "Visual hallucinations", "Age over 80"], 1, "Delirium begins abruptly with inattention and fluctuation over hours days; dementia creeps over years with attention spared early. Both can coexist, baseline collateral decides acuity.", ["Incorrect. Both impair memory.", "Correct. Attention plus acute fluctuation.", "Incorrect. Hallucinations occur in both (Lewy).", "Incorrect. Age predisposes, not defines."], "Cannot attend, changes by hour: delirium."),
  mcq("bk2-psy-102", "Which delirium subtype is most commonly missed and has poor prognosis?", ["Hyperactive", "Hypoactive", "Mixed without fluctuation", "Terminal only"], 1, "Quiet drowsy withdrawn hypoactive patients are labelled depressed or tired, delaying cause treatment; mixed is commonest overall in some series but hypoactive is the missed lethal one.", ["Incorrect. Agitation gets noticed and treated.", "Correct. Hypoactive delirium missed most.", "Incorrect. Fluctuation defines delirium generally.", "Incorrect. Occurs across settings."], "The quiet confused patient is the emergency."),
  mcq("bk2-psy-103", "First line management of delirium on a medical ward is what?", ["Routine haloperidol for all", "Find and treat causes plus multicomponent non drug bundle", "Sedate with benzodiazepine", "Restrain to bed"], 1, "Cause treatment (infection, fluids, drug stops) with orientation, hydration, mobilisation, sleep and sensory aids is therapy; antipsychotics reserve for severe distress danger, sedation and restraint worsen outcomes.", ["Incorrect. Routine antipsychotics do not shorten delirium.", "Correct. Causes plus HELP bundle first.", "Incorrect. Benzodiazepines worsen non withdrawal delirium.", "Incorrect. Restraint prolongs and injures."], "Treat the cause, free the patient."),
  mcq("bk2-psy-104", "Delirium in Parkinson or Lewy body dementia needing drug for dangerous agitation requires which caution?", ["Haloperidol high dose preferred", "Severe neuroleptic sensitivity risk; avoid typicals, specialist low dose atypical choices", "Benzodiazepine large dose safe", "No caution"], 1, "Dopamine blockade can cause life threatening sensitivity reactions in Lewy body disease; management maximises non drug measures, reviews dopaminergic and anticholinergic loads, and uses specialist guided low dose quetiapine or clozapine class options if unavoidable.", ["Incorrect. Typicals are most dangerous here.", "Correct. Neuroleptic sensitivity can kill.", "Incorrect. Sedation worsens falls and confusion.", "Incorrect. Caution is defining."], "Lewy brains fear dopamine blockers."),
  mcq("bk2-psy-105", "Benzodiazepines in delirium are treatment rather than poison in which scenario?", ["UTI delirium", "Alcohol or benzodiazepine withdrawal delirium", "Hypoxic delirium", "Anticholinergic delirium"], 1, "Withdrawal delirium is GABA deficit state where benzodiazepines are definitive; most other delirium worsens with them. Anticholinergic delirium instead needs culprit removal and supportive care.", ["Incorrect. Infection delirium worsens sedated.", "Correct. Withdrawal delirium needs benzodiazepines.", "Incorrect. Oxygen treats hypoxia.", "Incorrect. Stop anticholinergics, do not sedate deeper."], "Only withdrawal delirium drinks benzodiazepines safely."),
  mcq("bk2-psy-106", "CAM assessment requires which mandatory pair?", ["Memory loss plus hallucinations", "Acute fluctuating course plus inattention, plus disorganised thinking or altered level", "Depression plus insomnia", "Age plus fever"], 1, "Confusion Assessment Method algorithm: feature 1 acute fluctuation AND feature 2 inattention, plus either disorganised thinking or altered consciousness. Memory testing alone misses delirium.", ["Incorrect. Those are dementia or psychosis clues.", "Correct. Fluctuation plus inattention plus one more.", "Incorrect. Mood not CAM core.", "Incorrect. Fever is cause clue, not criterion."], "Fluctuates and cannot attend: CAM positive path."),
  mcq("bk2-psy-107", "Most common drug culprits precipitating delirium in elderly include which classes?", ["Statins and inhalers", "Anticholinergics, opioids, benzodiazepines and polypharmacy generally", "Vitamins", "Topical creams"], 1, "Anticholinergic burden, sedatives and opioids on vulnerable brains precipitate delirium; medication review stopping or reducing culprits is first intervention alongside infection and metabolic search.", ["Incorrect. Those rarely deliriate.", "Correct. Anticholinergic and sedative loads.", "Incorrect. Vitamins benign here.", "Incorrect. Topicals minimal systemic delirium risk."], "Review the drug chart before scanning the brain."),
  mcq("bk2-psy-108", "Delirium that persists unexplained for weeks should prompt consideration of which hidden cause among others?", ["Simple dehydration resolved", "Non convulsive seizures, subdural, autoimmune encephalitis re workup", "Normal ageing", "Discharge without follow up"], 1, "Persistent delirium is not a diagnosis to accept: occult infection, chronic subdural, autoimmune or metabolic disease and non convulsive status (EEG) need renewed hunt with neurology input.", ["Incorrect. Resolved causes end delirium.", "Correct. Re hunt hidden causes including EEG.", "Incorrect. Ageing never fluctuates like this.", "Incorrect. Follow up cognition is mandatory."], "Still delirious at week three: hunt again deeper."),
  mcq("bk2-psy-109", "Delirium prevention bundle proven to cut hospital incidence includes what?", ["Prophylactic antipsychotics", "Orientation, hydration, early mobilisation, sleep protocol, vision and hearing aids", "Bed rest and catheters", "Sedation at night"], 1, "Hospital Elder Life Program style multicomponent care prevents about a third of delirium; prophylactic antipsychotics lack prevention evidence and add harm.", ["Incorrect. Drugs do not prevent delirium.", "Correct. Multicomponent HELP bundle.", "Incorrect. Immobility and catheters provoke it.", "Incorrect. Sedatives precipitate it."], "Walk, water, glasses, sleep: delirium prevention."),
  mcq("bk2-psy-110", "After delirium resolves, patients carry increased long term risk of what, needing follow up?", ["No sequelae", "Dementia and mortality, with cognitive recovery sometimes months", "Mania only", "Improved cognition"], 1, "Delirium accelerates cognitive decline and predicts dementia diagnosis and death; families should expect slow recovery and clinics recheck cognition, function and mood after discharge.", ["Incorrect. Sequelae are substantial.", "Correct. Dementia and mortality risk rise.", "Incorrect. Mood risk is depression more than mania.", "Incorrect. Cognition worsens on average."], "Surviving delirium still endangers the brain.")]);

add("psy-personality", "Personality disorders", "personality_disorders", "Personality Disorders",
 ["Personality disorder clusters", "Borderline personality disorder", "Dialectical behaviour therapy", "Antisocial personality"],
 [step("**Personality disorders** are enduring, inflexible patterns of inner experience and behaviour deviating from cultural expectations, stable from adolescence or early adulthood, across cognition, affect, interpersonal function and impulse control, causing distress or impairment. They organise in clusters: A odd eccentric (paranoid, schizoid, schizotypal), B dramatic erratic (antisocial, borderline, histrionic, narcissistic), C anxious fearful (avoidant, dependent, obsessive compulsive personality). Modern dimensional models grade severity plus trait domains, but cluster literacy remains examination currency.", "Clusters: A odd, B dramatic, C anxious. Patterns are lifelong and pervasive, not episodes."),
  step("**Borderline (emotionally unstable) personality disorder** centres on abandonment fear, unstable intense relationships alternating idealisation and devaluation, identity disturbance, impulsivity, recurrent self-harm or suicidal gestures, affective instability within hours, chronic emptiness, intense anger and stress related dissociation or paranoid ideation (nine DSM criteria, five needed). Self-harm functions often as emotion regulation, not manipulation, and suicide completion still reaches several percent, demanding serious risk care without stigma.", "Borderline swings relationships and mood within hours, fears abandonment, self harms to regulate. Take every threat seriously."),
  step("**Dialectical behaviour therapy** (DBT) is first line for borderline disorder: skills in mindfulness, distress tolerance, emotion regulation and interpersonal effectiveness with individual therapy, skills group, coaching and therapist consultation team, cutting self-harm and hospitalisation. Mentalisation based and transference focused therapies also evidence. No drug treats core disorder; medicines target comorbid depression, anxiety or transient psychotic symptoms briefly (antipsychotic polypharmacy to avoid).", "DBT skills treat borderline core. No pill cures personality; drugs only treat comorbidity."),
  step("**Antisocial personality disorder** requires adulthood with conduct disorder before 15: pervasive disregard for rights (law breaking, deceit, impulsivity, aggression, safety disregard, irresponsibility, remorselessness), distinct from psychopathy construct (callous, superficial charm, measured by specialist tools). Management is primarily risk, safeguarding and treating comorbidity in forensic pathways; therapy evidence is limited (mentalisation and schema approaches developing). Avoidant personality differs from social anxiety by pervasiveness and identity level fear of rejection; obsessive compulsive personality pursues perfection and control without true obsessions or compulsions.", "Antisocial needs childhood conduct history. Personality is pattern, not episode: therapies and boundaries, not drug hunts.", tbl(["Cluster", "Members", "One line"], [["A odd", "Paranoid, schizoid, schizotypal", "Mistrustful, detached, eccentric"], ["B dramatic", "Antisocial, borderline, histrionic, narcissistic", "Rights, abandonment, attention, grandiosity"], ["C anxious", "Avoidant, dependent, obsessive compulsive personality", "Rejection fear, clinging, perfection control"], ["Treatment anchor", "Structured psychotherapies", "DBT for borderline self-harm"]]))],
 ["A odd, B dramatic, C anxious clusters", "Borderline: abandonment, instability, self-harm; DBT first line", "Antisocial requires conduct disorder before age 15", "No medication treats core personality disorder"],
 "Early temperament interacting with invalidating or traumatic environments derails emotion regulation and mentalisation development, entrenching interpersonal patterns that evoke confirming responses from others.",
 ["Borderline affective swings (hours, interpersonal) versus bipolar episodes (weeks, autonomous)", "Avoidant personality versus social anxiety disorder severity and pervasiveness", "OCPD perfectionism versus OCD intrusive rituals"],
 ["Longitudinal history from youth, collateral accounts", "Structured personality assessment in specialist settings", "Comorbidity and risk formulation at every contact"],
 [mcq("bk2-psy-111", "Cluster B personality disorders comprise which set?", ["Paranoid, schizoid, avoidant", "Antisocial, borderline, histrionic, narcissistic", "Dependent, obsessive compulsive", "Schizotypal alone"], 1, "Cluster B is dramatic, emotional and erratic: antisocial, borderline, histrionic, narcissistic. Cluster A is odd eccentric; cluster C anxious fearful.", ["Incorrect. Mixes A and C members.", "Correct. B dramatic set.", "Incorrect. Those are cluster C.", "Incorrect. Schizotypal is cluster A."], "B for theatrical storm: antisocial, borderline, histrionic, narcissistic."),
  mcq("bk2-psy-112", "First line treatment for borderline personality disorder with recurrent self-harm is what?", ["Long term benzodiazepine", "Dialectical behaviour therapy", "Antipsychotic combination", "ECT"], 1, "DBT specifically reduces self-harm, suicide attempts and admissions in RCTs by teaching regulation skills within validating therapy frame. Drugs lack core efficacy and polypharmacy accumulates harm.", ["Incorrect. Dependence worsens impulsivity.", "Correct. DBT first line.", "Incorrect. No antipsychotic treats core disorder.", "Incorrect. ECT targets severe mood or catatonia."], "Skills, not sedatives, for borderline storms."),
  mcq("bk2-psy-113", "Antisocial personality disorder diagnosis additionally requires evidence of what before age 15?", ["Psychosis", "Conduct disorder", "Mania", "Autism"], 1, "DSM requires conduct disorder onset before 15 plus adult disregard pattern from 18, linking childhood aggression, rule violation and cruelty trajectories. Adult criminality alone without childhood pattern does not suffice.", ["Incorrect. Psychosis not required.", "Correct. Conduct disorder before fifteen.", "Incorrect. Mania is episodic mood.", "Incorrect. Autism differs developmentally."], "No childhood conduct, no antisocial label."),
  mcq("bk2-psy-114", "Mood shifts in borderline disorder are best distinguished from bipolar hypomania how?", ["Borderline shifts last weeks", "Borderline reactivity lasts hours and is interpersonally triggered; bipolar episodes are days to weeks more autonomous", "Bipolar never cycles fast", "Only borderline elevates mood"], 1, "Borderline affective instability reacts to abandonment or rejection cues within hours returning to baseline dysphoria, while bipolar episodes sustain with neurovegetative and psychomotor change independent of triggers, guiding therapy versus mood stabilisers.", ["Incorrect. Weeks describes bipolar episodes.", "Correct. Hours plus interpersonal trigger equals borderline pattern.", "Incorrect. Rapid cycling bipolar exists but episodes persist days.", "Incorrect. Elevation belongs to bipolar spectrum."], "Hours after rejection: personality. Weeks unprovoked: bipolar."),
  mcq("bk2-psy-115", "Which pharmacotherapy is approved to treat core borderline personality disorder itself?", ["Fluoxetine specifically", "None; drugs target comorbidity only", "Mood stabilisers cure it", "Depot antipsychotic"], 1, "No medicine is licensed for core personality disorder; guidelines warn against polypharmacy, using time limited drugs for comorbid depression, anxiety or transient symptoms with review and stop dates.", ["Incorrect. SSRIs treat comorbid depression, not core.", "Correct. No drug treats core disorder.", "Incorrect. Stabilisers lack core cure evidence.", "Incorrect. Depots inappropriate for personality alone."], "Therapy treats personality; pills treat passengers."),
  mcq("bk2-psy-116", "Man aloof, solitary, flat, indifferent to praise or relationships since youth, content alone, most fits which cluster A disorder?", ["Paranoid", "Schizoid", "Schizotypal", "Avoidant"], 1, "Schizoid personality prefers solitude with emotional coldness and no desire for closeness, unlike avoidant who wants contact but fears rejection, schizotypal with magical oddity, paranoid with mistrust.", ["Incorrect. Paranoid mistrusts rather than detaches contentedly.", "Correct. Schizoid solitary detachment.", "Incorrect. Schizotypal adds eccentric beliefs and perceptual oddity.", "Incorrect. Avoidant longs for acceptance."], "Happy alone and flat: schizoid."),
  mcq("bk2-psy-117", "Obsessive compulsive personality disorder differs from OCD principally how?", ["Rituals are present in both equally", "OCPD is ego syntonic perfectionism and control without true intrusive obsessions or compulsive rituals", "OCPD has tics", "OCD is lifelong trait only"], 1, "OCPD traits (orderliness, perfectionism impairing completion, work devotion, rigidity) feel right to the person (ego syntonic), while OCD intrusions are unwanted (ego dystonic) with neutralising rituals. They can coexist.", ["Incorrect. Rituals define OCD, not OCPD.", "Correct. Ego syntonic perfectionism without rituals.", "Incorrect. Tics relate Tourette spectrum.", "Incorrect. OCD is episodic disorder, not trait label."], "Proud perfectionist is personality; tormented ritualiser is OCD."),
  mcq("bk2-psy-118", "Self-harm in borderline disorder is most accurately understood commonly as what?", ["Always manipulative attention seeking to dismiss", "Often emotion regulation or self punishment, still requiring full risk assessment", "Proof of psychosis", "Untreatable behaviour"], 1, "Functional analysis shows relief of unbearable affect, self punishment and communication of distress; dismissive manipulation framing harms care and misses real suicide mortality. DBT targets these functions with skills.", ["Incorrect. Stigmatising dismissal is unsafe and wrong.", "Correct. Regulation function, assess risk fully.", "Incorrect. Psychosis not implied.", "Incorrect. DBT demonstrably reduces it."], "Cutting regulates feelings; assess, never dismiss."),
  mcq("bk2-psy-119", "Schizotypal personality features include which additions beyond schizoid detachment?", ["Magical thinking, ideas of reference, perceptual distortions and eccentric appearance", "Conduct disorder", "Grandiosity", "Compulsive checking"], 0, "Schizotypal sits on schizophrenia spectrum with cognitive perceptual distortions, magical beliefs and odd speech or appearance plus social anxiety, carrying genetic kinship to schizophrenia.", ["Correct. Magical eccentric distortion set.", "Incorrect. Conduct belongs antisocial pathway.", "Incorrect. Grandiosity is narcissistic or manic.", "Incorrect. Checking is OCD spectrum."], "Detached plus magical equals schizotypal."),
  mcq("bk2-psy-120", "Dependent personality core pattern is what?", ["Excessive need to be taken care of with submissive clinging and fear of separation", "Detachment from relationships", "Disregard for rights", "Perfectionism"], 0, "Dependent personality subordinates own needs, fears making decisions or being alone, and urgently seeks new relationships when one ends, often tolerating mistreatment; therapy builds autonomy gradually.", ["Correct. Clinging care seeking dependence.", "Incorrect. Detachment is schizoid or avoidant pattern.", "Incorrect. Rights disregard is antisocial.", "Incorrect. Perfectionism is obsessive compulsive personality."], "Cannot decide alone, clings to care: dependent.")]);

let fail = 0;
for (const m of M) {
  for (const s of m.steps) if (!s.tx.includes("**")) s.tx = "**Key point.** " + s.tx;
  const lesson = { v: 1, module: m.id, subject: "psychiatry", title: m.title, minutes: 6, steps: m.steps, quiz: m.mcqs.map((x) => x.id), src: [], refs: [REF], gen: "AI", run: "books2-batch2-psychiatry", model: "muse-wonder (local authoring, no external API)", checks: { shape: true, numbers: true, drugs: true, verbatim: true, dashes: true, verify: true, redone: 0, dropped: 0, kbWords: 0, itemN: 10 } };
  const probs = LP.checkLesson(lesson);
  if (probs.length) { console.log("LESSON FAIL", m.id, probs); fail++; }
  fs.writeFileSync(path.join(ROOT, "prep/lessons/v1", m.id + ".json"), JSON.stringify(lesson, null, 1));
  const kb = { id: m.kb, name: m.kbName, aliases: m.aliases, class: "non_infective", system: "Psychiatry", specialty: "Psychiatry", referenceOnly: true, review: { status: "ai_drafted" }, reference: { source: REF, sourceEdition: "Topic map (2026-10-13)", pages: null, clinicalPearls: m.pearls, pathophysiology: m.patho, additionalDifferentials: m.diffs, additionalInvestigations: m.invs } };
  fs.writeFileSync(path.join(ROOT, "kb/reference", m.kb + ".json"), JSON.stringify(kb, null, 1));
  const overlay = { topic: m.id, set: "maikbook2", v: 1, items: m.mcqs.map((x) => ({ prov: "SMD", gen: "hand", set: "maikbook2", d: 2, cog: "application", credit: "StewardMD original medical knowledge base", licence: "CC BY 4.0 (StewardMD original)", licenceStandard: "CC BY 4.0", licenseUrl: "https://creativecommons.org/licenses/by/4.0", quality: { status: "automated_checks_passed", gates: { author_self_check: { note: "Author-verified against standard peer references" } } }, id: x.id, q: x.q, o: x.o, a: x.a, exp: x.exp, r: x.r, kp: x.kp })) };
  const dir = path.join(ROOT, "prep/overlays/maikbook2/psychiatry");
  fs.mkdirSync(dir, { recursive: true });
  fs.writeFileSync(path.join(dir, m.id + ".json"), JSON.stringify(overlay, null, 1));
}
const ixPath = path.join(ROOT, "prep/lessons/v1/index.json");
const ix = JSON.parse(fs.readFileSync(ixPath, "utf8"));
