oc.sets.maikbook2 = oc.sets.maikbook2 || {}; oc.sets.maikbook2.psychiatry = oc.sets.maikbook2.psychiatry || {};
for (const m of M) oc.sets.maikbook2.psychiatry[m.id] = 10;
fs.writeFileSync(ocPath, JSON.stringify(oc, null, 1));
console.log("modules:", M.length, "mcqs:", M.reduce((n, m) => n + m.mcqs.length, 0), "lesson failures:", fail);
